    ["Reset everything"] = "Tout réinitialiser",
    ["Reset to default"] = "Réinitialiser par défaut",
    ["Save"] = "Enregistrer",
    ["Saved."] = "Enregistré.",
    ["Search characters"] = "Rechercher des personnages",
    ["Short facts you write yourself, such as a name or a promise. The character knows them in every talk."] = "Courts faits que vous écrivez vous-même, comme un nom ou une promesse. Le personnage les connaît dans chaque discussion.",
    ["Short rules this character always follows when talking, for example: Never swear. Answer in one sentence."] = "Courtes règles que ce personnage suit toujours en parlant, par exemple : ne jurez jamais. Répondez en une phrase.",
    ["Short summary of earlier talks"] = "Bref résumé des discussions précédentes",
    ["Speaking rules"] = "Règles de parole",
    ["Speaking style"] = "Style de parole",
    ["That character was not found."] = "Ce personnage est introuvable.",
    ["The Local AI pack finds these. It is not installed or not ready, so none are collected now."] = "Le pack Local AI trouve ces éléments. Il n’est pas installé ou pas prêt, donc rien n’est recueilli pour l’instant.",
    ["The bio is too long. Keep it under {max} characters."] = "La biographie est trop longue. Gardez-la sous {max} caractères.",
    ["The bio is too short. Use at least {max} characters."] = "La biographie est trop courte. Utilisez au moins {max} caractères.",
    ["The conversation service is not running, so the editor cannot open. Restart the game."] = "Le service de conversation ne fonctionne pas, donc l’éditeur ne peut pas s’ouvrir. Redémarrez le jeu.",
    ["The editor could not be opened. Try again."] = "Impossible d’ouvrir l’éditeur. Réessayez.",
    ["The editor is closed. You can close this tab."] = "L’éditeur est fermé. Vous pouvez fermer cet onglet.",
    ["World rules"] = "Règles du monde",
    ["Rules for the whole world, used for every character in every talk: face to face, phone and group chats. Write facts and style, for example how people talk or what nobody knows. They never replace the mod’s own rules."] = "Règles pour tout le monde, appliquées à chaque personnage dans chaque échange : face à face, par téléphone et dans les discussions de groupe. Indiquez des faits et du style, par exemple la façon de parler des gens ou ce que personne ne sait. Elles ne remplacent jamais les règles du mod.",
    ["For example: Nobody in Night City knows V’s name unless V tells them. Everyone speaks casually."] = "Par exemple : Personne à Night City ne connaît le nom de V, sauf si V le dit. Tout le monde parle de façon décontractée.",
    ["Applies to every provider: Local AI, Mistral and Custom in the character prompt, and Convai through its dynamic info."] = "S’applique à tous les fournisseurs : Local AI, Mistral et Personnalisé dans le prompt du personnage, et Convai via ses infos dynamiques.",
    ["The world rules are too long. Keep them under {max} characters."] = "Les règles du monde sont trop longues. Gardez-les sous {max} caractères.",
    ["Revert changes"] = "Annuler les modifications",
    ["Clear the world rules?"] = "Effacer les règles du monde ?",
    ["The example lines are too long together. Keep them under {max} characters in all."] = "Les répliques d’exemple sont trop longues ensemble. Gardez-les sous {max} caractères au total.",
    ["The speaking style is too long. Keep it under {max} characters."] = "Le style de parole est trop long. Gardez-le sous {max} caractères.",
    ["Things they always know"] = "Ce qu’ils savent toujours",
    ["Too many example lines. Keep {max} or fewer."] = "Trop de répliques d’exemple. Gardez {max} ou moins.",
    ["Too many memories. Keep {max} or fewer."] = "Trop de souvenirs. Gardez {max} ou moins.",
    ["Too many rules. Keep {max} or fewer."] = "Trop de règles. Gardez {max} ou moins.",
    ["Who this character is, what they know and how they look. A long bio makes replies slower, so keep it tight."] = "Qui est ce personnage, ce qu’il sait et son apparence. Une longue biographie ralentit les réponses, alors soyez concis.",
    ["You have changes that are not saved. Leave without saving?"] = "Vous avez des modifications non enregistrées. Quitter sans enregistrer ?",
    ["{count} of {max}"] = "{count} sur {max}",
    ["Mature content"] = "Contenu pour adultes",
    ["Local AI model"] = "Modèle Local AI",
    ["Uncensored model"] = "Modèle sans censure",
    ["No model installed"] = "Aucun modèle installé",
    ["another model"] = "un autre modèle",
    ["The Local AI model you chose is missing, does not fit in the free graphics memory or did not start, so {model} was used instead."] = "Le modèle Local AI que vous avez choisi est absent, ne tient pas dans la mémoire graphique libre ou n'a pas pu démarrer ; {model} a donc été utilisé à la place.",
    ["The Local AI model you chose needs about {need} MB of graphics memory, but only {available} MB are available for it beside the game, so {model} was used instead."] = "Le modèle Local AI que vous avez choisi a besoin d'environ {need} Mo de mémoire graphique, mais seuls {available} Mo sont disponibles pour lui à côté du jeu, donc {model} a été utilisé à la place.",
    ["Local AI switched to {model}: the game is using most of your graphics memory."] = "Local AI est passée à {model} : le jeu utilise la majeure partie de votre mémoire vidéo.",
    ["Choose one of the listed Local AI models."] = "Choisissez l’un des modèles Local AI listés.",
    ["Main characters to invite"] = "Personnages principaux à inviter",
    ["Side characters to invite"] = "Personnages secondaires à inviter",
    ["Everyday people of Night City, from shopkeepers to fixers. Each joins as your own copy with their own personality."] = "Les gens ordinaires de Night City, des commerçants aux fixers. Chacun te rejoint sous forme de ta propre copie, avec sa propre personnalité.",
    ["Show only the characters whose name starts with this letter."] = "Affiche uniquement les personnages dont le nom commence par cette lettre.",
    ["Whose memories"] = "Souvenirs de qui",
    ["Invalid Mature content settings."] = "Paramètres de contenu pour adultes non valides.",
    ["Your message was not sent. Open the text box again and retype it."] = "Votre message n'a pas été envoyé. Rouvrez la zone de texte et saisissez-le à nouveau.",
    ["Not usable: {models}. See the Local AI notes, \"Add your own model\"."] = "Non utilisable : {models}. Voir les notes sur Local AI, « Ajouter votre propre modèle ».",
    ["an embedding model, not a chat model"] = "un modèle d'embedding, pas un modèle de chat",
    ["could not be read"] = "impossible à lire",
    ["file not found"] = "fichier introuvable",
    ["not a valid GGUF file"] = "fichier GGUF non valide",
    ["{name} (custom)"] = "{name} (personnalisé)",
    ["{name}: {reason}"] = "{name} : {reason}",
    ["Preparing {name}: waiting for the conversation service to connect…"] = "Préparation de {name} : en attente de la connexion du service de conversation…",
    ["Preparing {name}: waiting for the voice model to load…"] = "Préparation de {name} : en attente du chargement du modèle vocal…",
    ["Preparing {name}: waiting for the conversation connection to open…"] = "Préparation de {name} : en attente de l'ouverture de la connexion de conversation…",
    ["Preparing {name}: waiting for the game to place the character…"] = "Préparation de {name} : en attente de la mise en place du personnage par le jeu…",
    ["Preparing {name}: waiting for the memory service…"] = "Préparation de {name} : en attente du service de mémoire…",
    ["Preparing {count} more companions…"] = "Préparation de {count} autres compagnons…",
    ["The conversation service did not answer. Wait a moment, then invite again."] = "Le service de conversation n'a pas répondu. Patientez un instant, puis invitez à nouveau.",
    ["The voice model did not load. Check the voice in Settings or choose another one, then invite again."] = "Le modèle vocal n'a pas été chargé. Vérifiez la voix dans Paramètres ou choisissez-en une autre, puis invitez à nouveau.",
    ["The memory service did not respond. Check your connection, then invite again."] = "Le service de mémoire n'a pas répondu. Vérifiez votre connexion, puis invitez à nouveau.",
    ["The conversation connection did not open. Check your connection, then invite again."] = "La connexion de conversation ne s'est pas ouverte. Vérifiez votre connexion, puis invitez à nouveau.",
    ["Convai sign-in is busy right now. Wait a few minutes, then invite again."] = "La connexion à Convai est occupée pour le moment. Attendez quelques minutes, puis invitez à nouveau.",
    ["The Convai daily limit is used up. Choose another provider in Settings, or invite again tomorrow."] = "La limite quotidienne de Convai est atteinte. Choisissez un autre fournisseur dans Paramètres, ou invitez à nouveau demain.",
    ["The Convai daily limit is used up. It resets at {time}. Choose another provider in Settings, or invite again then."] = "La limite quotidienne de Convai est atteinte. Réinitialisation à {time}. Choisissez un autre fournisseur dans Paramètres, ou invitez à nouveau ensuite.",
    ["Calls are not available during combat."] = "Les appels ne sont pas disponibles pendant un combat.",
    ["Calls are not available right now."] = "Les appels ne sont pas disponibles pour le moment.",
    ["Holocall ended: combat started."] = "Holoappel terminé : le combat a commencé.",
    ["Holocall with {name} ended."] = "Holoappel avec {name} terminé.",
    ["Live picture unavailable. The call continues with the portrait."] = "Image en direct indisponible. L'appel continue avec le portrait.",
    ["This contact cannot take a holocall."] = "Ce contact ne peut pas recevoir de holoappel.",
    ["You are already on a call."] = "Vous êtes déjà en appel.",
    ["Ask a companion to drive to your selected map waypoint.\n\nGet into the passenger seat when they are ready."] = "Demandez à un compagnon de conduire jusqu’au repère choisi sur la carte.\n\nMontez sur le siège passager quand il est prêt.",
    ["Auto: follows the completed encounter in this save.\n\nCasual: speaks with that familiarity.\n\nOrdinary: keeps her usual manner.\n\nIt does not imply an ongoing relationship."] = "Auto : suit la rencontre terminée dans cette sauvegarde.\n\nDécontracté : parle avec cette familiarité.\n\nOrdinaire : garde son comportement habituel.\n\nN’implique pas de relation en cours.",
    ["Auto: follows the relationship in this save.\n\nRomantic: speaks to V as a partner.\n\nOrdinary: keeps their usual manner.\n\nOnly changes how they talk, never your game choices."] = "Auto : suit la relation dans cette sauvegarde.\n\nRomantique : parle à V comme à un partenaire.\n\nOrdinaire : garde sa manière habituelle.\n\nModifie seulement leur façon de parler, jamais vos choix dans le jeu.",
    ["Bluetooth audio arrives a little late, so lips and subtitles can run ahead of the voice. This holds them back to match, for every voice.\n\nAuto: 150 ms while Windows plays through Bluetooth, none otherwise. Pick a value if your headset is faster or slower.\n\nThe game’s own dialogue has the same delay and does not correct it."] = "L’audio Bluetooth arrive un peu en retard : les lèvres et les sous-titres peuvent devancer la voix. Ce réglage les retarde pour les synchroniser, pour toutes les voix.\n\nAuto : 150 ms quand Windows joue via Bluetooth, aucun décalage sinon. Choisissez une valeur si votre casque est plus rapide ou plus lent.\n\nLes dialogues du jeu ont le même retard et ne sont pas corrigés.",
    ["Chat history stays available across game launches.\n\nForgetting a character also clears their saved Chat messages and drafts. Forgetting all memories clears all saved chats."] = "L’historique du chat reste disponible d’une session à l’autre.\n\nOublier un personnage efface aussi ses messages et brouillons du Chat. Effacer tous les souvenirs efface tous les chats enregistrés.",
    ["Custom models are ones you added; they join the default choice by size."] = "Les modèles personnalisés sont ceux que vous avez ajoutés, classés par taille.",
    ["Forget all memories applies to these characters.\n\nBrowsing the catalogue or inviting a companion does not add anyone to this count."] = "Effacer tous les souvenirs s’applique à ces personnages.\n\nParcourir le catalogue ou inviter un compagnon n’ajoute personne à ce décompte.",
    ["Talk to story characters"] = "Parler aux personnages de l’histoire",
    ["{name} is busy right now."] = "{name} est occupé pour l’instant.",
    ["{name} is not in your head right now."] = "{name} n’est pas dans votre tête pour l’instant.",
    ["{name} is a story character. Turn on Talk to story characters in Esc > Mods."] = "{name} : activez « Parler aux personnages de l’histoire » dans Esc > Mods.",
    ["Talk to ordinary NPCs is off. Turn it on in Esc > Mods."] = "Parler aux PNJ ordinaires est désactivé. Activez-le dans Esc > Mods.",
    ["{name} is a child and cannot be talked to."] = "Impossible de parler à {name} : c’est un enfant.",
    ["{name} is not a person and cannot be talked to."] = "Impossible de parler à {name} : ce n’est pas une personne.",
    ["{name} cannot be talked to: the mod cannot tell which voice fits."] = "Impossible de parler à {name} : le mod ne peut pas déterminer quelle voix convient.",
    ["If a character stops answering, voices stop or an error appears: choose Generate report and send the file it names to the developer, with a short note about what you were doing.\n\nThe logs listed below show what went wrong."] = "Si un personnage cesse de répondre, si les voix s’arrêtent ou si une erreur apparaît : choisissez Générer le rapport et envoyez le fichier indiqué au développeur, avec une courte note sur ce que vous faisiez.\n\nLes journaux listés ci-dessous montrent ce qui a mal tourné.",
    ["Invited characters are prepared immediately. Their memories start when you actually talk to them.\n\nOne player identity is shared across all saves and stays the same after forgetting.\n\nCurrent game context describes the world you have loaded."] = "Les personnages invités sont préparés immédiatement. Leurs souvenirs commencent quand vous leur parlez réellement.\n\nUne identité de joueur unique est partagée entre toutes les sauvegardes et reste la même après un oubli.\n\nLe contexte de jeu actuel décrit le monde que vous avez chargé.",
    ["Only Mature models found. Turn on Mature content to use them."] = "Modèles pour adultes uniquement. Activez le Contenu pour adultes.",
    ["Something on this PC (a firewall or security software) is blocking the connection to the model server you added."] = "Un élément de ce PC (un pare-feu ou un logiciel de sécurité) bloque la connexion au serveur de modèle que vous avez ajouté.",
    ["Never allowed: sex with minors or without consent, sex about real people, hate, real-world weapon or drug instructions. A safety check enforces the minors rule."] = "Jamais autorisé : sexe avec des mineurs ou sans consentement, sexe avec de vraies personnes, haine, instructions réelles d’armes ou de drogues. Un contrôle de sécurité applique la règle sur les mineurs.",
    ["Off: replies are text only and no voice is generated.\n\nWith Subtitles off as well, automatic reactions stay silent."] = "Désactivé : texte seul, aucune voix.\n\nAvec les Sous-titres aussi désactivés, les réactions automatiques restent muettes.",
    ["See what each character remembers and make one or all of them forget.\n\nMemories are kept across saves."] = "Voir les souvenirs de chaque personnage ; en effacer un ou tous.\n\nConservés d’une sauvegarde à l’autre.",
    ["Voxtral · not with Mature"] = "Voxtral · pas avec 18+",
    ["Voxtral is not used with Mature content."] = "Voxtral n’est pas utilisé avec le Contenu pour adultes.",
    ["Needs Local AI or Custom."] = "Nécessite Local AI ou Personnalisé.",
    ["Mature content is turned off because you chose a model that is not a Mature model."] = "Le Contenu pour adultes est désactivé, car tu as choisi un modèle qui n’est pas pour adultes.",
    ["Strong language, graphic violence, drugs and, between consenting adults, flirting and sex. Adults only (18+). Needs Local AI or Custom."] = "Langage fort, violence graphique, drogues et, entre adultes consentants, flirt et sexe. Réservé aux adultes (18+). Nécessite Local AI ou Personnalisé.",
    ["Voxtral · Mistral cloud"] = "Voxtral · Cloud Mistral",
    ["Voxtral · needs Mistral key"] = "Voxtral · clé Mistral requise",
    ["{name} (custom · too large)"] = "{name} (personnalisé · trop grand)",
    ["{name} (custom, {size} GB, needs {need} GB)"] = "{name} (personnalisé, {size} Go, nécessite {need} Go)",
    ["{name} (custom, {size} GB, too large for this card)"] = "{name} (personnalisé, {size} Go, trop grand pour cette carte)",
    ["Clear memories about you for every character you have talked to.\n\nYour player identity stays. A confirmation comes first."] = "Effacer vos souvenirs chez tous les personnages avec qui vous avez parlé.\n\nVotre identité de joueur reste. Une confirmation vient d’abord.",
    ["Saves a report file you can send to the developer.\n\nAPI keys, tokens, IDs, microphone audio and conversation text are left out. Without the conversation service, a shorter report is made from the files the game can read."] = "Enregistre un fichier de rapport à envoyer au développeur.\n\nLes clés d’API, jetons, identifiants, audio du micro et texte des conversations sont exclus. Sans le service de conversation, un rapport plus court est créé à partir des fichiers lisibles par le jeu.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: installed."] = "Modèles non censurés du Mature pack (pour Local AI) : effet complet. Les standards refusent surtout le sexe. Pack : installé.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: not installed (optional, on this mod’s Hugging Face page)."] = "Modèles non censurés du Mature pack (pour Local AI) : effet complet. Les standards refusent surtout le sexe. Pack : non installé (optionnel, sur la page Hugging Face du mod).",
    ["Until you choose one, Local AI loads the largest model that fits your free graphics memory.\n\nOne model at a time; a change applies when it next loads. A model that is missing, too large or failing is replaced by the largest that fits, with one notice."] = "Sans choix, Local AI charge le plus grand modèle qui tient dans votre mémoire graphique libre.\n\nUn modèle à la fois ; un changement prend effet au prochain chargement. Modèle manquant, trop gros ou défaillant : remplacé par le plus grand qui tient, avec un seul avis.",
    ["Convai did not accept your API key. Check it in Settings > Conversation provider."] = "Convai n'a pas accepté votre clé d'API. Vérifiez-la dans Paramètres > Fournisseur de conversation.",
    ["Local AI could not start. Check Local AI in Settings > Conversation provider."] = "Local AI n'a pas pu démarrer. Vérifiez Local AI dans Paramètres > Fournisseur de conversation.",
    ["Mistral did not accept your key. Check it in Settings > Conversation provider."] = "Mistral n'a pas accepté votre clé. Vérifiez-la dans Paramètres > Fournisseur de conversation.",
    ["Mistral has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "Mistral n'a pas encore de clé, Convai est donc utilisé. Ajoutez votre clé dans Paramètres > Fournisseur de conversation.",
    ["Speaking to companions needs Convai for now. Set Conversation provider to Convai free tier in Settings > Conversation provider, or type your message."] = "Parler aux compagnons nécessite Convai pour le moment. Définissez Fournisseur de conversation sur Convai (offre gratuite) dans Paramètres > Fournisseur de conversation, ou tapez votre message.",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Conversation provider."] = "Votre clé d'API Convai a atteint la limite de son offre. Réessayez plus tard ou ajoutez une autre clé dans Paramètres > Fournisseur de conversation.",
    ["Paste"] = "Coller",
    ["no Omni pack"] = "sans pack OmniVoice",
    ["Add your Convai API key below to see and buy a plan."] = "Ajoutez votre clé d'API Convai ci-dessous pour voir les offres et en acheter une.",
    ["Add your Convai API key first."] = "Ajoutez d'abord votre clé d'API Convai.",
    ["Add your Convai API key first: copy it, then choose Paste on the Convai API key row."] = "Ajoutez d'abord votre clé d'API Convai : copiez-la, puis choisissez Coller sur la ligne Clé d'API Convai.",
    ["Asking Convai for the payment page…"] = "Demande de la page de paiement à Convai…",
    ["Asks Convai which plan your key has now. After paying, it can take about 15 seconds."] = "Demande à Convai quelle offre votre clé possède maintenant. Après le paiement, cela peut prendre environ 15 secondes.",
    ["Billed every month."] = "Facturé chaque mois.",
    ["Billed once a year."] = "Facturé une fois par an.",
    ["Buy"] = "Acheter",
    ["Check"] = "Vérifier",
    ["Check my plan"] = "Vérifier mon offre",
    ["Checking your plan…"] = "Vérification de votre offre…",
    ["Choose Check my plan to ask Convai."] = "Choisissez Vérifier mon offre pour interroger Convai.",
    ["Contacting Convai…"] = "Contact de Convai…",
    ["Convai could not start the payment. Try again later."] = "Convai n'a pas pu lancer le paiement. Réessayez plus tard.",
    ["Convai did not accept your API key."] = "Convai n'a pas accepté votre clé d'API.",
    ["Convai does not show a paid plan for your key yet."] = "Convai n'affiche pas encore d'offre payante pour votre clé.",
    ["Convai has not confirmed your plan yet. Check it in Settings > Convai paid tier."] = "Convai n'a pas encore confirmé votre offre. Vérifiez-la dans Paramètres > Offre payante Convai.",
    ["Convai paid tier"] = "Offre payante Convai",
    ["Convai’s payment page is open in your browser. Your plan is active about 15 seconds after you pay."] = "La page de paiement de Convai est ouverte dans votre navigateur. Votre offre est active environ 15 secondes après le paiement.",
    ["Convai’s payment service did not answer. Try again in a moment."] = "Le service de paiement de Convai n'a pas répondu. Réessayez dans un instant.",
    ["Convai’s plans for this mod: more Convai conversations on your own Convai API key. Opens a page with the plans and their prices."] = "Offres Convai pour ce mod : plus de conversations Convai avec votre propre clé d'API Convai. Ouvre une page avec les offres et leurs prix.",
    ["Conversations with Convai API key chosen as the provider use this plan."] = "Les conversations avec la clé d'API Convai choisie comme fournisseur utilisent cette offre.",
    ["Get your Convai API key"] = "Obtenir votre clé d'API Convai",
    ["Manage or cancel plan"] = "Gérer ou annuler l'offre",
    ["Free"] = "Gratuit",
    ["Gamer, monthly"] = "Gamer, mensuel",
    ["Gamer, yearly"] = "Gamer, annuel",
    ["Gamer Pro, monthly"] = "Gamer Pro, mensuel",
    ["Gamer Pro, yearly"] = "Gamer Pro, annuel",
    ["Current plan"] = "Offre actuelle",
    ["This is your current plan. To change or cancel it, choose Manage or cancel plan below."] = "Voici votre offre actuelle. Pour la modifier ou l'annuler, choisissez Gérer ou annuler l'offre ci-dessous.",
    ["No key added"] = "Aucune clé ajoutée",
    ["Not checked yet"] = "Pas encore vérifié",
    ["Opened in your browser."] = "Ouvert dans votre navigateur.",
    ["Opening the page in your browser…"] = "Ouverture de la page dans votre navigateur…",
    ["Opens Convai’s payment page (Stripe) in your browser. You pay Convai directly; the mod never sees your card. Your plan is active about 15 seconds after you pay, and conversations then use your Convai API key."] = "Ouvre la page de paiement de Convai (Stripe) dans votre navigateur. Vous payez Convai directement ; le mod ne voit jamais votre carte. Votre offre est active environ 15 secondes après le paiement, puis les conversations utilisent votre clé d'API Convai.",
    ["Opens convai.com in your browser. Sign in or make a free account, copy your API key, then come back and choose Paste below."] = "Ouvre convai.com dans votre navigateur. Connectez-vous ou créez un compte gratuit, copiez votre clé d'API, puis revenez et choisissez Coller ci-dessous.",
    ["Opens your Convai billing page in your browser. Sign in with the same Convai account to change or cancel your plan."] = "Ouvre votre page de facturation Convai dans votre navigateur. Connectez-vous avec le même compte Convai pour modifier ou annuler votre offre.",
    ["Plans"] = "Offres",
    ["Plans Convai made for this mod. They give your own Convai API key more conversations; the free tier stays as it is."] = "Offres créées par Convai pour ce mod. Elles donnent plus de conversations à votre propre clé d'API Convai ; l'offre gratuite reste inchangée.",
    ["Prices in US dollars. You can cancel at any time on Convai’s billing page."] = "Prix en dollars américains. Vous pouvez annuler à tout moment sur la page de facturation de Convai.",
    ["The conversation service is not running, so plans cannot be shown. Restart the game."] = "Le service de conversation ne tourne pas, les offres ne peuvent donc pas être affichées. Redémarrez le jeu.",
    ["This key has no paid plan. Choose a plan below."] = "Cette clé n'a pas d'offre payante. Choisissez une offre ci-dessous.",
    ["Your Convai plan"] = "Votre offre Convai",
    ["Your Convai plan is active."] = "Votre offre Convai est active.",
    ["Your Convai plan is active. Choose Convai API key in Settings > Conversation provider."] = "Votre offre Convai est active. Choisissez Clé d'API Convai dans Paramètres > Fournisseur de conversation.",
    ["Your Convai plan is active. Conversations now use your Convai API key."] = "Votre offre Convai est active. Les conversations utilisent maintenant votre clé d'API Convai.",
    ["Your browser could not be opened."] = "Votre navigateur n'a pas pu être ouvert.",
    ["Your plan could not be read right now. Try again in a moment."] = "Votre offre n'a pas pu être lue pour le moment. Réessayez dans un instant.",
    ["{count} Convai interactions a month."] = "{count} interactions Convai par mois.",
    ["{plan}, {price} a month"] = "{plan}, {price} par mois",
    ["{plan}, {price} a year"] = "{plan}, {price} par an",
    ["Sign in with Convai"] = "Se connecter avec Convai",
    ["Sign in"] = "Se connecter",
    ["Opens Convai’s sign-in page in your browser.\n\nSign in or make a free account, and your Convai API key is saved on this computer, the same as Paste. You have five minutes."] = "Ouvre la page de connexion de Convai dans votre navigateur.\n\nConnectez-vous ou créez un compte gratuit : votre clé d'API Convai est alors enregistrée sur cet ordinateur, comme avec Coller. Vous avez cinq minutes.",
    ["Opening Convai’s sign-in page in your browser…"] = "Ouverture de la page de connexion de Convai dans votre navigateur…",
    ["Sign in on the Convai page in your browser. Your key is saved here when you finish."] = "Connectez-vous sur la page Convai dans votre navigateur. Votre clé sera enregistrée ici une fois la procédure terminée.",
    ["Signed in. Your Convai API key is saved."] = "Connexion réussie. Votre clé d'API Convai est enregistrée.",
    ["The sign-in took too long. Choose Sign in with Convai to try again."] = "La connexion a pris trop de temps. Choisissez Se connecter avec Convai pour réessayer.",
    ["The sign-in did not finish. Try again, or copy your key from convai.com and choose Paste."] = "La connexion n'a pas abouti. Réessayez, ou copiez votre clé depuis convai.com et choisissez Coller.",
    ["Choose one of the listed voices for V."] = "Choisissez l’une des voix proposées pour V.",
    ["Pocket · On your PC"] = "Pocket · Sur votre PC",
    ["Johnny in your head"] = "Johnny dans votre tête",
    ["Johnny in your head is off. Turn it on in Settings > Conversations."] = "Johnny dans votre tête est désactivé. Activez-le dans Paramètres > Conversations.",
    ["Choose how often Johnny speaks up."] = "Fréquence des interventions de Johnny.",
    ["A display name is too long. Keep each one under {max} characters."] = "Un nom d’affichage est trop long. Gardez chacun sous {max} caractères.",
    ["A clip you add replaces the shipped voice of this character for Pocket, OmniVoice and the Voxtral cloud voice."] = "Un clip que vous ajoutez remplace la version d’origine de la voix de ce personnage pour Pocket, OmniVoice et la voix cloud Voxtral.",
    ["A new or removed clip counts from the next line this character speaks, once the current reply is over. Nothing needs restarting."] = "Un clip ajouté ou supprimé compte dès la prochaine réplique de ce personnage, une fois la réponse en cours terminée. Rien à redémarrer.",
    ["A record name can only use letters, digits, dots, dashes and underscores, for example Character.Rebecca."] = "Un nom d’enregistrement ne peut contenir que des lettres, des chiffres, des points, des tirets et des tirets bas, par exemple Character.Rebecca.",
    ["Add a display name"] = "Ajouter un nom d’affichage",
    ["Add a record name"] = "Ajouter un nom d’enregistrement",
    ["Add a record name or a display name, so the game can find this character."] = "Ajoutez un nom d’enregistrement ou un nom d’affichage, pour que le jeu puisse trouver ce personnage.",
    ["Add voice clip"] = "Ajouter un clip vocal",
    ["Another character of yours, {other}, already answers to this record or name."] = "Un autre de vos personnages, {other}, répond déjà à cet enregistrement ou à ce nom.",
    ["Choose a gender"] = "Choisissez un genre",
    ["Choose a gender."] = "Choisissez un genre.",
    ["Chosen file: {name} ({size}). It is checked when you save it."] = "Fichier choisi : {name} ({size}). Il est vérifié quand vous l’enregistrez.",
    ["Chosen file: {name}, {seconds} seconds."] = "Fichier choisi : {name}, {seconds} secondes.",
    ["Clip removed."] = "Clip supprimé.",
    ["Delete character"] = "Supprimer le personnage",
    ["Delete {name}? The character, its voice clip and what it remembers of you are removed."] = "Supprimer {name} ? Le personnage, son clip vocal et tout ce qu’il retient de vous sont supprimés.",
    ["Display names"] = "Noms d’affichage",
    ["Female"] = "Féminin",
    ["Filled in from the character you were facing: {name}."] = "Rempli à partir du personnage en face de vous : {name}.",
    ["For example: Character.Rebecca"] = "Par exemple : Character.Rebecca",
    ["For example: Rebecca"] = "Par exemple : Rebecca",
    ["Gender"] = "Genre",
    ["Give the character a name."] = "Donnez un nom au personnage.",
    ["How the game finds this character"] = "Comment le jeu trouve ce personnage",
    ["It picks the voice when the character has no clip."] = "Le genre choisit la voix quand le personnage n’a pas de clip.",
    ["Male"] = "Masculin",
    ["Memories"] = "Souvenirs",
    ["Name"] = "Nom",
    ["New character"] = "Nouveau personnage",
    ["No clip yet."] = "Pas encore de clip.",
    ["Optional. Pocket, OmniVoice and the Voxtral cloud voice copy a clip you add. Without one the character speaks with a generic voice that fits the gender."] = "Facultatif. Pocket, OmniVoice et la voix cloud Voxtral copient un clip que vous ajoutez. Sans clip, le personnage parle avec une voix générique adaptée à son genre.",
    ["Play saved clip"] = "Écouter le clip enregistré",
    ["Record names"] = "Noms d’enregistrement",
    ["Remove clip"] = "Supprimer le clip",
    ["Remove the voice clip? The character goes back to a generic voice."] = "Supprimer le clip vocal ? Le personnage revient à une voix générique.",
    ["Remove the voice clip? {name} goes back to the shipped voice."] = "Supprimer le clip vocal ? {name} revient à la version d’origine de sa voix.",
    ["Save clip"] = "Enregistrer le clip",
    ["Save the character first. Then it can have a voice clip, and it starts to remember your talks."] = "Enregistrez d’abord le personnage. Il pourra ensuite avoir un clip vocal et commencer à se souvenir de vos conversations.",
    ["Saved clip: {seconds} seconds."] = "Clip enregistré : {seconds} secondes.",
    ["Saved. The clip is a little long: 10 to 18 seconds copies best."] = "Enregistré. Le clip est un peu long : 10 à 18 secondes donnent la meilleure copie.",
    ["Saved. The clip is a little short: 10 to 18 seconds copies best."] = "Enregistré. Le clip est un peu court : 10 à 18 secondes donnent la meilleure copie.",
    ["That file is not a recording the voices can read. Use a WAV, MP3, OGG or FLAC file."] = "Ce fichier n’est pas un enregistrement que les voix peuvent lire. Utilisez un fichier WAV, MP3, OGG ou FLAC.",
    ["That file is too big for a voice clip."] = "Ce fichier est trop volumineux pour un clip vocal.",
    ["The clip is mostly silence. Use a clip where somebody is talking most of the time."] = "Le clip est presque entièrement silencieux. Utilisez un clip où quelqu’un parle la plupart du temps.",
    ["The clip is too long. Use at most {max} seconds."] = "Le clip est trop long. Utilisez {max} secondes au maximum.",
    ["The clip is too short. Use at least {min} seconds."] = "Le clip est trop court. Utilisez au moins {min} secondes.",
    ["The game did not name anyone. Face the character, then choose Settings > Edit characters > Open in the game again."] = "Le jeu n’a désigné personne. Tournez-vous vers le personnage, puis choisissez de nouveau Paramètres > Modifier les personnages > Ouvrir dans le jeu.",
    ["The game recognises the person you talk to by a record name, a display name, or both. A record name looks like Character.Rebecca or NCA.Rebecca. Add at least one."] = "Le jeu reconnaît la personne à qui vous parlez grâce à un nom d’enregistrement, un nom d’affichage, ou les deux. Un nom d’enregistrement ressemble à Character.Rebecca ou NCA.Rebecca. Ajoutez-en au moins un.",
    ["The name is too long. Keep it under {max} characters."] = "Le nom est trop long. Gardez-le sous {max} caractères.",
    ["The name of the character’s record in the game files."] = "Le nom de l’enregistrement du personnage dans les fichiers du jeu.",
    ["The name the character goes by. They give it when somebody asks who they are."] = "Le nom sous lequel le personnage est connu. Il le donne quand quelqu’un lui demande qui il est.",
    ["The name the game shows for the character."] = "Le nom que le jeu affiche pour le personnage.",
    ["The recording is distorted. Record it again, a little quieter."] = "L’enregistrement est déformé. Refaites-le, un peu moins fort.",
    ["The recording is too low in quality. Use at least {min} Hz."] = "La qualité de l’enregistrement est trop faible. Utilisez au moins {min} Hz.",
    ["The recording is too quiet to copy. Record it louder, or closer to the microphone."] = "L’enregistrement est trop faible pour être copié. Enregistrez plus fort, ou plus près du micro.",
    ["The saved clip could not be loaded."] = "Le clip enregistré n’a pas pu être chargé.",
    ["The words said in the clip are too long. Keep them under {max} characters."] = "Le texte prononcé dans le clip est trop long. Gardez-le sous {max} caractères.",
    ["This character speaks with a generic voice that fits the gender."] = "Ce personnage parle avec une voix générique adaptée à son genre.",
    ["This character speaks with the shipped voice."] = "Ce personnage parle avec la version d’origine de sa voix.",
    ["This computer cannot convert that file. Save it as a WAV and try again."] = "Cet ordinateur ne peut pas convertir ce fichier. Enregistrez-le en WAV, puis réessayez.",
    ["Too many display names. Keep {max} or fewer."] = "Trop de noms d’affichage. Gardez-en {max} au maximum.",
    ["Too many record names. Keep {max} or fewer."] = "Trop de noms d’enregistrement. Gardez-en {max} au maximum.",
    ["Type the words said in the clip, at least {min} characters."] = "Saisissez les mots prononcés dans le clip, au moins {min} caractères.",
    ["Type what the clip says, as spoken. OmniVoice needs it to copy the voice."] = "Saisissez ce que dit le clip, tel qu’il est prononcé. OmniVoice en a besoin pour copier la voix.",
    ["Use the character I’m facing"] = "Utiliser le personnage en face de moi",
    ["Use {min} to {max} seconds of one person speaking clearly, with no music or other voices. {goodMin} to {goodMax} seconds copies best. WAV, MP3, OGG or FLAC."] = "Utilisez entre {min} et {max} secondes d’une seule personne qui parle clairement, sans musique ni autres voix. Entre {goodMin} et {goodMax} secondes donnent la meilleure copie. WAV, MP3, OGG ou FLAC.",
    ["Voice"] = "Voix",
    ["You have as many voice clips as the editor keeps ({max}). Remove one first."] = "Vous avez autant de clips vocaux que l’éditeur en garde ({max}). Supprimez-en d’abord un.",
    ["Who this character is, what they know and how they look. Writing it as “I am …” works best. A long bio makes replies slower, so keep it tight."] = "Qui est ce personnage, ce qu’il sait et à quoi il ressemble. Le mieux est de l’écrire à la première personne, « Je suis … ». Une longue biographie ralentit les réponses, alors gardez-la courte.",
    ["Words said in the clip"] = "Mots prononcés dans le clip",
    ["You have made as many characters as the editor keeps ({max}). Delete one first."] = "Vous avez créé autant de personnages que l’éditeur peut en garder ({max}). Supprimez-en un d’abord.",
    ["Your character"] = "Votre personnage",
    ["Your characters"] = "Vos personnages",
    ["{other} already has a profile in the mod, and that profile always wins. Use another record or name."] = "{other} a déjà un profil dans le mod, et ce profil l’emporte toujours. Utilisez un autre enregistrement ou un autre nom.",
    ["A pack is one folder too deep. See Help in Settings."] = "Un pack a un dossier de trop. Voir Aide dans Paramètres.",
    ["All files found."] = "Tous les fichiers trouvés.",
    ["Browser"] = "Navigateur",
    ["Found."] = "Trouvé.",
    ["Found: {list}."] = "Trouvé : {list}.",
    ["Game version"] = "Version du jeu",
    ["Graphics card"] = "Carte graphique",
    ["Internet"] = "Internet",
    ["Loaded."] = "Chargé.",
    ["Local AI could not start. Generate a report below and send it, or choose another conversation provider."] = "Local AI n’a pas pu démarrer. Générez un rapport ci-dessous et envoyez-le, ou choisissez un autre fournisseur de conversation.",
    ["Local AI found no graphics card it can use. It needs an NVIDIA or AMD card with a current driver. Update the driver, or choose another conversation provider."] = "Local AI n’a trouvé aucune carte graphique utilisable. Elle a besoin d’une carte NVIDIA ou AMD avec un pilote à jour. Mettez le pilote à jour ou choisissez un autre fournisseur de conversation.",
    ["Missing: {files}. Extract the Scripts zip into the Cyberpunk 2077 folder again and let it replace the files."] = "Manquants : {files}. Réextrayez le zip Scripts dans le dossier de Cyberpunk 2077 et laissez-le remplacer les fichiers.",
    ["Mod files"] = "Fichiers du mod",
    ["Mod manager"] = "Gestionnaire de mods",
    ["Moved into place from {folder}: {packs}."] = "Déplacés depuis {folder} : {packs}.",
    ["No Local AI pack found. Download one from the mod’s Hugging Face page and extract it into the Cyberpunk 2077 folder, or choose another conversation provider."] = "Aucun pack Local AI trouvé. Téléchargez-en un depuis la page Hugging Face du mod et extrayez-le dans le dossier de Cyberpunk 2077, ou choisissez un autre fournisseur de conversation.",
    ["No problem found. Select a line to see what was checked."] = "Aucun problème trouvé. Sélectionnez une ligne pour voir ce qui a été vérifié.",
    ["No sign of the conversation service in this session: the Runtime is missing or did not load. Extract the full install zip (AI-Companions-LLM) straight into the Cyberpunk 2077 folder (not into a new folder), check that red4ext/plugins/AiNpcCyberpunkMod is there, then restart the game. The full install is on the mod’s Nexus Mods page."] = "Aucune trace du service de conversation dans cette session : le Runtime est absent ou ne s’est pas chargé. Extrayez le zip d’installation complet (AI-Companions-LLM) directement dans le dossier de Cyberpunk 2077 (pas dans un nouveau dossier), vérifiez que red4ext/plugins/AiNpcCyberpunkMod est présent, puis redémarrez le jeu. L’installation complète se trouve sur la page du mod sur Nexus Mods.",
    ["None found: installed by hand."] = "Aucun trouvé : installé à la main.",
    ["None installed. They are optional."] = "Aucun installé. Ils sont facultatifs.",
    ["Not needed: Local AI and the voice run on this PC."] = "Inutile : Local AI et la voix tournent sur ce PC.",
    ["Not used"] = "Non utilisé",
    ["Not your conversation provider. Choose it in Settings > Conversation provider."] = "Ce n’est pas votre fournisseur de conversation. Choisissez-le dans Paramètres > Fournisseur de conversation.",
    ["Note"] = "Remarque",
    ["OK"] = "OK",
    ["Optional packs"] = "Packs facultatifs",
    ["Problem"] = "Problème",
    ["Problems found: {count}. Select a line marked Problem to read what to do."] = "Problèmes trouvés : {count}. Sélectionnez une ligne marquée Problème pour lire quoi faire.",
    ["RED4ext is not loaded. Install it from Nexus Mods, then restart the game. It also starts the conversation service."] = "RED4ext n’est pas chargé. Installez-le depuis Nexus Mods, puis redémarrez le jeu. Il lance aussi le service de conversation.",
    ["Reached {host}."] = "{host} joignable.",
    ["Scripts and Runtime"] = "Scripts et Runtime",
    ["Scripts {scripts} and Runtime {runtime}."] = "Scripts {scripts} et Runtime {runtime}.",
    ["Scripts {scripts} on Runtime base {runtime}."] = "Scripts {scripts} sur la base du Runtime {runtime}.",
    ["These Scripts {scripts} need the Runtime base {required} or newer, and your Runtime is {runtime}. Extract the full install zip (AI-Companions-LLM, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Ces Scripts {scripts} nécessitent la base du Runtime {required} ou plus récente, et votre Runtime est {runtime}. Extrayez le zip d’installation complet (AI-Companions-LLM, sur Nexus Mods) dans le dossier de Cyberpunk 2077, puis redémarrez le jeu.",
    ["The Runtime is older than {required}. Get the full install zip."] = "Le Runtime est plus ancien que {required}. Récupérez le ZIP complet.",
    ["Setup check"] = "Vérification de l’installation",
    ["Some mod files are missing. Extract the update zip again. See Help in Settings."] = "Fichiers du mod manquants. Réextrayez le Update-ZIP. Voir Aide dans Paramètres.",
    ["Some pack files could not be moved into place because different files are already there. Extract the pack into the Cyberpunk 2077 folder again and let it replace the files."] = "Certains fichiers du pack n’ont pas pu être déplacés, car d’autres fichiers différents sont déjà là. Réextrayez le pack dans le dossier de Cyberpunk 2077 et laissez-le remplacer les fichiers.",
    ["The Runtime is incomplete ({code}). Extract the full install zip (AI-Companions-LLM) into the Cyberpunk 2077 folder again and let it replace the files, then restart the game."] = "Le Runtime est incomplet ({code}). Extrayez à nouveau le zip d’installation complet (AI-Companions-LLM) dans le dossier de Cyberpunk 2077 en remplaçant les fichiers, puis redémarrez le jeu.",
    ["Mod Organizer 2 does not show a file of the Runtime to the program. Close the game and Mod Organizer 2, extract the full install zip (AI-Companions-LLM) into the Cyberpunk 2077 folder by hand, then start the game."] = "Mod Organizer 2 n’affiche pas un fichier du Runtime au programme. Fermez le jeu et Mod Organizer 2, extrayez à la main le zip d’installation complet (AI-Companions-LLM) dans le dossier de Cyberpunk 2077, puis démarrez le jeu.",
    ["The settings file of the launcher, launcher.ini, is missing from red4ext/plugins/AiNpcCyberpunkMod, so the game cannot start the conversation service. Extract the full install zip (AI-Companions-LLM) straight into the Cyberpunk 2077 folder again (by hand, also with Vortex) and let it replace the files, then restart the game."] = "Le fichier de réglages du lanceur, launcher.ini, est absent de red4ext/plugins/AiNpcCyberpunkMod, donc le jeu ne peut pas démarrer le service de conversation. Extrayez à nouveau le zip d’installation complet (AI-Companions-LLM) directement dans le dossier Cyberpunk 2077 (à la main, même avec Vortex) en remplaçant les fichiers, puis redémarrez le jeu.",
    ["The conversation service cannot reach the internet. See Help in Settings."] = "Le service de conversation n’a pas accès à Internet. Voir Aide dans Paramètres.",
    ["The conversation service cannot reach {host}. Allow Node.js through your firewall or antivirus (Windows asks once; choose Allow), check your internet, then restart the game."] = "Le service de conversation ne peut pas joindre {host}. Autorisez Node.js dans votre pare-feu ou antivirus (Windows le demande une seule fois ; choisissez Autoriser l’accès), vérifiez votre connexion Internet, puis redémarrez le jeu.",
    ["The conversation service could not start ({code}). Restart the game. If it happens again, generate a report below and send it."] = "Le service de conversation n’a pas pu démarrer ({code}). Redémarrez le jeu. Si cela se reproduit, générez un rapport ci-dessous et envoyez-le.",
    ["The conversation service did not start. Is the Runtime installed? See Help in Settings."] = "Le service de conversation n’a pas démarré. Runtime installé ? Voir Aide dans Paramètres.",
    ["The game version could not be read."] = "La version du jeu n’a pas pu être lue.",
    ["This PC cannot look up {host}. Check your internet connection, then restart the game."] = "Ce PC ne peut pas résoudre {host}. Vérifiez votre connexion Internet, puis redémarrez le jeu.",
    ["Open r6/logs/redscript_rCURRENT.log. A mod it names is why the scripts did not load."] = "Ouvrez r6/logs/redscript_rCURRENT.log. Un mod cité là empêche les scripts de charger.",
    ["This mod’s scripts did not load. Open r6/logs/redscript_rCURRENT.log. If the error names another mod, that mod is the problem. Missing or old Codeware or redscript, or a game version other than {game}, can also cause it."] = "Les scripts de ce mod ne se sont pas chargés. Ouvrez r6/logs/redscript_rCURRENT.log. Si l’erreur nomme un autre mod, c’est lui le problème. Un Codeware ou redscript manquant ou ancien, ou une version du jeu autre que {game}, peut aussi en être la cause.",
    ["Missing: {names}. Install them and restart the game."] = "Manquants : {names}. Installez-les et redémarrez le jeu.",
    ["Install or update: {names}. Then restart the game."] = "Installez ou mettez à jour : {names}. Puis redémarrez le jeu.",
    ["Codeware is too old. Update it from Nexus Mods, then restart the game."] = "Codeware est trop ancien. Mettez-le à jour depuis Nexus Mods, puis redémarrez le jeu.",
    ["Version {version}."] = "Version {version}.",
    ["Version {version}. The mod is tested on {game} only, so some things may not work."] = "Version {version}. Le mod n’est testé que sur la {game} : certaines choses peuvent ne pas fonctionner.",
    ["Version {version}. These files are the mod build for game {build}. Extract the full install zip made for game {game}, from the mod’s Nexus Mods page, into the Cyberpunk 2077 folder, then restart the game."] = "Version {version}. Ces fichiers sont la build du mod pour le jeu {build}. Extrayez le zip d’installation complet prévu pour le jeu {game}, depuis la page du mod sur Nexus Mods, dans le dossier de Cyberpunk 2077, puis redémarrez le jeu.",
    ["Vortex. Install the optional packs by hand into the Cyberpunk 2077 folder, as the install steps say. Install the full install zip as one mod and update that mod with each new full install zip."] = "Vortex. Installez à la main les packs facultatifs dans le dossier de Cyberpunk 2077, comme l’indiquent les étapes d’installation. Installez le zip d’installation complet comme un mod et mettez ce mod à jour avec chaque nouveau zip d’installation complet.",
    ["{name} is missing. Install it from Nexus Mods, then restart the game."] = "{name} est manquant. Installez-le depuis Nexus Mods, puis redémarrez le jeu.",
    ["{name}, {memory} GB of video memory."] = "{name}, {memory} Go de mémoire vidéo.",
    ["{packs} is one folder too deep, in {folder}. Restart the game and the mod moves it into place. If it is still there afterwards, move the red4ext folder inside it into the Cyberpunk 2077 folder."] = "{packs} contient un dossier de trop, dans {folder}. Redémarrez le jeu : le mod le déplace au bon endroit. S’il y est encore ensuite, déplacez le dossier red4ext qui s’y trouve dans le dossier de Cyberpunk 2077.",
    ["Add an endpoint URL and a model ID first."] = "Ajoutez d’abord l’URL d’endpoint et l’ID du modèle.",
    ["Convai: the custom provider is not set up yet"] = "Convai : fournisseur personnalisé non configuré",
    ["Copy the base URL from your provider, for example https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 or http://localhost:11434/v1 (Ollama). It is read from the clipboard once and saved on this computer.\n\nOnly this computer and your home network may use http://. You can also fill in endpoint=, model= and api-key= in player-custom-endpoint.txt in the conversation service folder.\n\nNothing is sent until you choose this provider or press Test connection."] = "Copiez l’URL de base de votre fournisseur, par exemple https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 ou http://localhost:11434/v1 (Ollama). Elle est lue une seule fois depuis le presse-papiers et enregistrée uniquement sur cet ordinateur.\n\nSeuls cet ordinateur et votre réseau domestique peuvent utiliser http://. Vous pouvez aussi renseigner endpoint=, model= et api-key= dans player-custom-endpoint.txt, dans le dossier du service de conversation.\n\nRien n’est envoyé tant que vous ne choisissez pas ce fournisseur ou n’appuyez pas sur Tester la connexion.",
    ["Copy the model ID from your provider first, for example meta-llama/llama-3.1-8b-instruct on OpenRouter or llama3.2 on Ollama. It is read from the clipboard once and saved on this computer."] = "Copiez d’abord l’ID du modèle de votre fournisseur, par exemple meta-llama/llama-3.1-8b-instruct sur OpenRouter ou llama3.2 sur Ollama. Il est lu une seule fois depuis le presse-papiers et enregistré uniquement sur cet ordinateur.",
    ["Copy your API key from your provider first. It is read from the clipboard once and saved on this computer only. A server on your own computer, such as Ollama or LM Studio, usually needs no key."] = "Copiez d’abord votre clé d’API auprès de votre fournisseur. Elle est lue une seule fois depuis le presse-papiers et enregistrée uniquement sur cet ordinateur. Un serveur installé sur votre propre ordinateur, comme Ollama ou LM Studio, n’a généralement pas besoin de clé.",
    ["Custom (OpenAI-compatible)"] = "Personnalisé (API OpenAI)",
    ["Custom API key"] = "Clé d’API propre",
    ["Custom endpoint URL"] = "URL d’endpoint propre",
    ["Custom model ID"] = "ID de modèle propre",
    ["Custom provider replies are spoken by a local voice instead of the Convai cloud voice."] = "Réponses du fournisseur personnalisé : voix locale, pas la voix cloud de Convai.",
    ["Custom: key not accepted"] = "Personnalisé : clé non acceptée",
    ["Custom: model unavailable"] = "Personnalisé : modèle indisponible",
    ["Custom: out of credits"] = "Personnalisé : crédits épuisés",
    ["Custom: rate limited for now"] = "Personnalisé : limité pour l’instant",
    ["Deletes the saved endpoint URL. The custom provider needs one to answer."] = "Supprime l’URL d’endpoint enregistrée. Le fournisseur personnalisé en a besoin pour répondre.",
    ["Deletes the saved key. Replies from the custom provider are then asked for without a key."] = "Supprime la clé enregistrée. Les réponses du fournisseur personnalisé sont ensuite demandées sans clé.",
    ["Deletes the saved model ID. The custom provider needs one to answer."] = "Supprime l’ID de modèle enregistré. Le fournisseur personnalisé en a besoin pour répondre.",
    ["Failed"] = "Échec",
    ["It answered in {ms} ms."] = "Réponse en {ms} ms.",
    ["It could not be saved."] = "Impossible de l’enregistrer.",
    ["Model ID: {model}"] = "ID de modèle : {model}",
    ["Only https:// works outside this computer and your home network."] = "Seul https:// fonctionne hors de cet ordinateur et de votre réseau domestique.",
    ["Paste API key"] = "Coller la clé d’API",
    ["Paste endpoint URL"] = "Coller l’URL",
    ["Paste model ID"] = "Coller l’ID du modèle",
    ["Sends one tiny message to your endpoint with the saved model ID and key, and shows how it answered. It uses next to nothing of your credits."] = "Envoie un message minuscule à votre endpoint avec l’ID de modèle et la clé enregistrés, et affiche sa réponse. Cela consomme presque rien de vos crédits.",
    ["Test"] = "Tester",
    ["Test connection"] = "Tester la connexion",
    ["Testing the connection…"] = "Test de la connexion…",
    ["Testing…"] = "Test en cours…",
    ["That is too long."] = "C’est trop long.",
    ["That was not accepted."] = "Ce n’a pas été accepté.",
    ["The account is out of credits. Add credits with your provider."] = "Le compte n’a plus de crédits. Ajoutez-en auprès de votre fournisseur.",
    ["The address must start with https:// or http://."] = "L’adresse doit commencer par https:// ou http://.",
    ["The address sends you somewhere else. Use the final address from your provider."] = "L’adresse vous redirige ailleurs. Utilisez l’adresse finale fournie par votre fournisseur.",
    ["That address is a web page, not the API. For OpenRouter use https://openrouter.ai/api/v1."] = "Cette adresse est une page web, pas l’API. Pour OpenRouter, utilisez https://openrouter.ai/api/v1.",
    ["That address is a web page, not the API. Use the API address from your provider."] = "Cette adresse est une page web, pas l’API. Utilisez l’adresse de l’API fournie par votre fournisseur.",
    ["A model ID is a short name like that, not a web address."] = "Un ID de modèle est un nom court de ce genre, pas une adresse web.",
    ["The clipboard does not hold a model ID."] = "Le presse-papiers ne contient pas d’ID de modèle.",
    ["The clipboard does not hold a web address."] = "Le presse-papiers ne contient pas d’adresse web.",
    ["The clipboard does not hold an API key."] = "Le presse-papiers ne contient pas de clé d’API.",
    ["The clipboard is empty. Copy it first."] = "Le presse-papiers est vide. Copiez d’abord.",
    ["The connection test failed."] = "Le test de connexion a échoué.",
    ["The connection works. The endpoint accepted your model and key."] = "La connexion fonctionne. L’endpoint a accepté votre modèle et votre clé.",
    ["The conversation service is not running, so nothing can be tested. Restart the game."] = "Le service de conversation ne tourne pas, rien ne peut donc être testé. Redémarrez le jeu.",
    ["The custom provider did not accept your key. Check it in Settings > Conversation provider."] = "Clé refusée par le fournisseur personnalisé. Voir Paramètres > Fournisseur de conversation.",
    ["The custom provider did not answer. Check its address in Settings, or try again."] = "Le fournisseur personnalisé n’a pas répondu. Vérifiez l’adresse dans Paramètres ou réessayez.",
    ["The custom provider does not know that model ID. Check it in Settings."] = "Fournisseur personnalisé : ID de modèle inconnu. Vérifiez dans Paramètres.",
    ["The custom provider is not set up, so Convai is used. Add its URL and model ID in Settings."] = "Pas de fournisseur personnalisé : Convai utilisé. Ajoutez URL et ID du modèle dans Paramètres.",
    ["The custom provider is rate limiting you. Try again in a moment."] = "Le fournisseur personnalisé limite les requêtes. Réessayez dans un instant.",
    ["The custom provider says your account is out of credits. Add credits there, then try again."] = "Plus de crédits chez le fournisseur personnalisé. Ajoutez-en, puis réessayez.",
    ["The endpoint URL was removed."] = "L’URL d’endpoint a été supprimée.",
    ["The endpoint answered with no text. Check the model ID."] = "L’endpoint a répondu sans texte. Vérifiez l’ID du modèle.",
    ["The endpoint did not accept your API key."] = "L’endpoint n’a pas accepté votre clé d’API.",
    ["The endpoint did not answer. Check its address."] = "L’endpoint n’a pas répondu. Vérifiez son adresse.",
    ["The endpoint does not know that model ID."] = "L’endpoint ne connaît pas cet ID de modèle.",
    ["The endpoint is rate limiting you. Try again in a moment."] = "L’endpoint vous limite pour l’instant. Réessayez dans un instant.",
    ["The endpoint is rate limiting you. Wait about {seconds} seconds, then try again."] = "L’endpoint vous limite. Attendez environ {seconds} secondes, puis réessayez.",
    ["The endpoint refused the request. Check the model ID and the address."] = "L’endpoint a refusé la requête. Vérifiez l’ID du modèle et l’adresse.",
    ["The endpoint reported an error on its side. Try again in a moment."] = "L’endpoint signale une erreur de son côté. Réessayez dans un instant.",
    ["The endpoint took too long to answer."] = "L’endpoint a mis trop de temps à répondre.",
    ["The model ID was removed."] = "L’ID du modèle a été supprimé.",
    ["The provider said: {detail}"] = "Le fournisseur a dit : {detail}",
    ["This address is not encrypted, which is fine on your own computer or home network."] = "Cette adresse n’est pas chiffrée, ce qui est acceptable sur votre ordinateur ou votre réseau domestique.",
    ["Use the base URL only: no password, query or #."] = "Indiquez seulement l’URL de base, sans mot de passe, requête ni #.",
    ["Waiting for the endpoint to answer…"] = "En attente de la réponse de l’endpoint…",
    ["Custom: free daily limit reached"] = "Personnalisé : limite quotidienne gratuite atteinte",
    ["New address saved. Paste your API key again for it."] = "Nouvelle adresse enregistrée. Collez à nouveau votre clé d’API.",
    ["The free daily limit for this model was reached. It resets at {time}."] = "Limite quotidienne gratuite atteinte pour ce modèle. Réinitialisation à {time}.",
    ["The free daily limit for this model was reached. Try again after it resets."] = "Limite quotidienne gratuite atteinte pour ce modèle. Réessayez après la réinitialisation.",
    ["This model spends its reply on thinking. Choose a non-reasoning model in Settings."] = "Ce modèle réfléchit sans répondre. Choisissez un modèle sans raisonnement dans Paramètres.",
    ["All"] = "Tous",
    ["Also changed: {names}."] = "Également modifié : {names}.",
    ["Choose any character from the list below. They do not need to be in your current party."] = "Choisissez un personnage de la liste ci-dessous. Il n'a pas besoin d'être dans votre groupe actuel.",
    ["Defaults restored."] = "Valeurs par défaut rétablies.",
    ["Drag the slider, or press left and right, to turn the page."] = "Faites glisser le curseur ou appuyez sur les flèches gauche et droite pour changer de page.",
    ["How loud the companions’ and characters’ voices are. 100 is the normal level, 150 the default.\n\nAbove 100 the voices get louder, with a limiter so they do not crackle. V’s voice has its own setting below, and the game’s own dialogue and sounds do not change.\n\nThe next reply uses it."] = "Le volume des voix des compagnons et des personnages. 100 est le niveau normal, 150 le niveau par défaut.\n\nAu-dessus de 100, les voix sont plus fortes, avec un limiteur pour éviter les craquements. La voix de V a son propre réglage plus bas, et les dialogues et les sons du jeu ne changent pas.\n\nLa prochaine réponse l’utilise.",
    ["How loud V’s own voice is, for V’s typed and microphone lines. 100 is the normal level, 150 the default.\n\nAbove 100 the voice gets louder, with a limiter so it does not crackle. The companions’ voices and the game’s own dialogue and sounds do not change.\n\nThe next line uses it."] = "Le volume de la voix propre de V, pour les répliques tapées et celles dites au micro. 100 est le niveau normal, 150 le niveau par défaut.\n\nAu-dessus de 100, la voix est plus forte, avec un limiteur pour éviter les craquements. Les voix des compagnons et les dialogues et les sons du jeu ne changent pas.\n\nLa prochaine réplique l’utilise.",
    ["Not available right now."] = "Non disponible pour le moment.",
    ["Open Settings to restore its defaults."] = "Ouvrez Paramètres pour rétablir ses valeurs par défaut.",
    ["Page"] = "Page",
    ["Show only the models whose name starts with this letter."] = "N’affiche que les modèles dont le nom commence par cette lettre.",
    ["Starts with"] = "Commence par",
    ["Open AI NPC Cyberpunk Mod in the Mods list."] = "Ouvrez AI NPC Cyberpunk Mod dans la liste Mods.",
    ["The settings could not be saved. Nothing was changed."] = "Les paramètres n'ont pas pu être enregistrés. Rien n'a été modifié.",
    ["Send error reports automatically"] = "Rapports d'erreur automatiques",
    ["Error reports go to the developer. Turn them off in Settings > Privacy and help."] = "Rapports envoyés automatiquement. Désactivez dans Paramètres > Confidentialité et aide.",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI"] = "La gestion des compagnons nécessite Mod Configuration Menu 0.10.5+ ou Native Settings UI",
    ["Update Mod Configuration Menu to 0.10.5 or newer, or install Native Settings UI"] = "Mettez Mod Configuration Menu à jour (0.10.5+) ou installez Native Settings UI",
    ["Stand up to open the Companion Manager"] = "Levez-vous pour ouvrir la gestion des compagnons",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI {nsui} or newer. Either one is enough. Install one from Nexus Mods, then restart the game."] = "La gestion des compagnons nécessite Mod Configuration Menu 0.10.5 ou plus récent, ou Native Settings UI {nsui} ou plus récent. L’un ou l’autre suffit. Installez l’un des deux depuis Nexus Mods, puis redémarrez le jeu.",
    ["Mod Configuration Menu is too old. Update it to 0.10.5 or newer, or install Native Settings UI, then restart the game."] = "Mod Configuration Menu est trop ancien. Mettez-le à jour en 0.10.5 ou plus récent, ou installez Native Settings UI, puis redémarrez le jeu.",
    ["Previous page"] = "Page précédente",
    ["Next page"] = "Page suivante",
    ["Starts with: {letter}"] = "Commence par : {letter}",
    ["Characters and party"] = "Personnages et groupe",
    ["Load a save first"] = "Chargez une partie",
    ["Inviting characters and managing your party need a loaded game."] = "Inviter des personnages et gérer votre groupe demande une partie chargée.",
    ["Voxtral (recommended)"] = "Voxtral (recommandé)",
    ["Defaults"] = "Par défaut",
    ["Press Confirm to put every setting back to its default."] = "Appuyez sur Confirmer pour remettre chaque paramètre à sa valeur par défaut.",
    ["Local AI stopped working and was restarted."] = "Local AI a cessé de fonctionner et a été relancée.",
    ["Local AI runs mostly on your processor here, so replies will be slow."] = "Local AI tourne surtout sur votre processeur ici, donc les réponses seront lentes.",
    ["Local AI is back on your graphics card, so replies are faster again."] = "Local AI est de retour sur votre carte graphique, les réponses sont plus rapides.",
    ["Voice files"] = "Fichiers vocaux",
    ["The voice files are incomplete. Reinstall the Full download from Nexus Mods."] = "Les fichiers vocaux sont incomplets. Réinstallez le zip d’installation complet depuis Nexus Mods.",
    ["The voice files are incomplete, so the voices and the microphone cannot start. Reinstall the Full download from Nexus Mods: extract it into the Cyberpunk 2077 folder and let it replace the files, then restart the game."] = "Les fichiers vocaux sont incomplets, donc les voix et le microphone ne peuvent pas démarrer. Réinstallez le zip d’installation complet depuis Nexus Mods : extrayez-le dans le dossier de Cyberpunk 2077 et laissez-le remplacer les fichiers, puis redémarrez le jeu.",
    ["Changes this mod’s menus and notices only.\n\nCharacter voices and the language you talk in are separate. The microphone uses this language as a hint for non-English speech."] = "Ne change que les menus et les notifications de ce mod.\n\nLes voix des personnages et la langue dans laquelle vous parlez sont distinctes. Le micro utilise cette langue comme indication pour une parole non anglaise.",
    ["Deletes the saved key."] = "Supprime la clé enregistrée.",
    ["The Convai cloud voice cannot use Natural speech, so it was turned off."] = "La voix cloud de Convai ne peut pas utiliser la parole naturelle, elle a donc été désactivée.",
    ["Custom endpoint"] = "Endpoint personnalisé",
    ["Speaks up often"] = "Prend la parole souvent",
    ["Speaks up rarely"] = "Prend la parole rarement",
    ["The address, API key and model ID of your OpenAI-compatible provider, and a connection test. Used when Custom is the Conversation provider."] = "L’adresse, la clé API et l’ID de modèle de votre fournisseur compatible OpenAI, ainsi qu’un test de connexion. Utilisé lorsque Personnalisé est le fournisseur de conversation.",
    ["OmniVoice · needs Omni pack"] = "OmniVoice · pack Omni requis",
    ["OmniVoice · needs Omni voice"] = "OmniVoice · voix Omni requise",
    ["Requires the Companion voices to be an OmniVoice choice"] = "Exige que les voix des compagnons soient le choix OmniVoice",
    ["V’s voice switches from OmniVoice to Pocket."] = "La voix de V passe d’OmniVoice à Pocket.",
    ["V’s voice"] = "Voix de V",
    ["V (male voice)"] = "V (voix masculine)",
    ["V (female voice)"] = "V (voix féminine)",
    ["Used for V’s typed lines: Pocket, OmniVoice and the Voxtral cloud voice copy it."] = "Utilisée pour les répliques tapées de V : Pocket, OmniVoice et la voix cloud Voxtral la copient.",
    ["V speaks with the voice of your installed V voice mod, or the shipped V voice."] = "V parle avec la voix de votre mod vocal de V installé, ou avec la voix d’origine de V.",
    ["Remove the voice clip? V goes back to the voice of your installed V voice mod, or the shipped V voice."] = "Supprimer le clip vocal ? V revient à la voix de votre mod vocal de V installé, ou à la voix d’origine de V.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Replies show as text. Choose Pocket in Settings to hear voices."] = "OmniVoice nécessite une carte graphique NVIDIA, et ce PC n’en a aucune qui fonctionne. Les réponses s’affichent en texte. Choisissez Pocket dans Paramètres pour entendre les voix.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Companions are using {voice} instead."] = "OmniVoice nécessite une carte graphique NVIDIA, et ce PC n’en a aucune qui fonctionne. Les compagnons utilisent {voice} à la place.",
    ["OmniVoice needs NVIDIA"] = "OmniVoice nécessite NVIDIA",
    ["This PC has no NVIDIA graphics card, which OmniVoice needs. OmniVoice will not start here. Choose Pocket to hear voices."] = "Ce PC n’a pas de carte graphique NVIDIA, dont OmniVoice a besoin. OmniVoice ne démarrera pas ici. Choisissez Pocket pour entendre les voix.",
    ["{voice} · needs NVIDIA card"] = "{voice} · nécessite une carte NVIDIA",
    ["{language} replies show as text: the {language} multilingual pack is missing."] = "Les réponses en {language} s’affichent en texte : le pack multilingue {language} est absent.",
    ["French"] = "Français",
    ["Italian"] = "Italien",
    ["German"] = "Allemand",
    ["Spanish"] = "Espagnol",
    ["Portuguese"] = "Portugais",
    ["OmniVoice needs more graphics memory than is free next to the game. Pocket is used."] = "OmniVoice nécessite plus de mémoire graphique que l’espace libre à côté du jeu. Pocket est utilisé.",
    ["Windows ran out of memory for the voice. A larger paging file or closing other apps helps."] = "Windows manque de mémoire pour la voix. Agrandir le fichier d’échange ou fermer des apps.",
    ["OmniVoice needs 12 GB"] = "OmniVoice nécessite 12 Go",
    ["{voice} · needs 12 GB card"] = "{voice} · nécessite une carte de 12 Go",
    ["The graphics card in this PC has less than the 12 GB OmniVoice needs next to the game. If it cannot start, Pocket is used. Choose Pocket to skip the wait."] = "La carte graphique de ce PC a moins des 12 Go dont OmniVoice a besoin à côté du jeu. Si OmniVoice ne peut pas démarrer, Pocket est utilisé. Choisissez Pocket pour éviter l’attente.",
    ["Forget all memories ({count} characters)"] = "Effacer tous les souvenirs ({count} personnages)",
    ["Dynamic info"] = "Infos en direct",
    ["Location"] = "Lieu",
    ["Time and weather"] = "Heure et météo",
    ["The hour of the day and the weather in Night City.\n\nOff: nobody is told the time or the weather, and the mod stops reading them from the game."] = "L’heure de la journée et la météo à Night City.\n\nDésactivé : personne n’est informé de l’heure ni de la météo, et le mod cesse de les lire dans le jeu.",
    ["Company and vehicle"] = "Compagnie et véhicule",
    ["Who else is with V, whether V is on foot or in a vehicle, and what a companion is doing beside V.\n\nOff: none of this is sent, and the mod stops reading it from the game."] = "Qui d’autre accompagne V, si V est à pied ou en véhicule, et ce que fait un compagnon à côté de V.\n\nDésactivé : rien de tout cela n’est envoyé, et le mod cesse de le lire dans le jeu.",
    ["Health, heat and fights"] = "Santé, recherche et combats",
    ["V’s health, the police heat on V, and the last fight V was in.\n\nOff: none of this is sent, and the mod stops reading it from the game."] = "La santé de V, la recherche de la police contre V et le dernier combat de V.\n\nDésactivé : rien de tout cela n’est envoyé, et le mod cesse de le lire dans le jeu.",
    ["V’s money"] = "Argent de V",
    ["A rough idea of how many eddies V has: nearly broke, short, comfortable or rich.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Une idée approximative du nombre d’eddies de V : presque fauché, juste, à l’aise ou riche.\n\nDésactivé : ce n’est pas envoyé, et le mod cesse de le lire dans le jeu.",
    ["V’s gear and clothes"] = "Équipement et tenue de V",
    ["What V wears and carries: clothes, weapons and cyberware that can be seen.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Ce que V porte et transporte : vêtements, armes et cyberware visibles.\n\nDésactivé : ce n’est pas envoyé, et le mod cesse de le lire dans le jeu.",
    ["V’s gender and lifepath"] = "Genre et parcours de V",
    ["Whether V is a woman or a man, and V’s lifepath: Nomad, Street Kid or Corpo.\n\nOff: it is not sent with a turn, and the mod stops reading it for that. Your story’s own facts may still reflect your lifepath."] = "Si V est une femme ou un homme, et le parcours de V : Nomade, Gamin des rues ou Corpo.\n\nDésactivé : ce n’est pas envoyé à chaque échange, et le mod cesse de le lire pour cela. Les faits de votre histoire peuvent malgré tout refléter votre parcours.",
    ["Quest and journal"] = "Quêtes et journal",
    ["V’s tracked quest and its objectives, the jobs V has open and the journal history.\n\nWhat each character knows about your story stays on.\n\nOff: none of this is sent. The mod stops scanning the journal for it, unless Johnny’s remarks are on."] = "La quête suivie par V et ses objectifs, les contrats ouverts de V et l’historique du journal.\n\nCe que chaque personnage sait de votre histoire reste actif.\n\nDésactivé : rien de tout cela n’est envoyé. Le mod cesse de chercher ces infos dans le journal, sauf si les remarques de Johnny sont activées.",
    ["Recent game dialogue"] = "Dialogues récents",
    ["The last lines spoken in scenes and V’s chosen replies, so a character can pick up from what was just said.\n\nOff: they are not sent."] = "Les dernières répliques prononcées dans les scènes et les réponses choisies par V, pour qu’un personnage puisse reprendre ce qui vient d’être dit.\n\nDésactivé : elles ne sont pas envoyées.",
    ["The Runtime is out of date. Get the full install zip."] = "Le Runtime est obsolète. Récupérez le zip d’installation complet.",
    ["The Scripts and Runtime do not match. Update whichever is older. See Help in Settings."] = "Scripts et Runtime ne correspondent pas. Mettez à jour le plus ancien. Voir Aide dans Paramètres.",
    ["Scripts {scripts} and Runtime {runtime} do not match: the Runtime is out of date. Extract the full install zip (AI-Companions-LLM, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Scripts {scripts} et Runtime {runtime} ne correspondent pas : le Runtime est obsolète. Extrayez le zip d’installation complet (AI-Companions-LLM, sur Nexus Mods) dans le dossier de Cyberpunk 2077, puis redémarrez le jeu.",
    ["Scripts {scripts} and Runtime {runtime} do not match. If the Scripts are older, install the update zip from Nexus Mods. If the Runtime is older, install the full install zip (AI-Companions-LLM). Extract into the Cyberpunk 2077 folder, then restart the game."] = "Scripts {scripts} et Runtime {runtime} ne correspondent pas. Si les Scripts sont plus anciens, installez le zip de mise à jour depuis Nexus Mods. Si le Runtime est plus ancien, installez le zip d’installation complet (AI-Companions-LLM). Extrayez dans le dossier de Cyberpunk 2077, puis redémarrez le jeu.",
    ["The conversation service did not answer the setup check, so its Runtime is probably older than these Scripts. Extract the full install zip (AI-Companions-LLM, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Le service de conversation n’a pas répondu à la vérification de l’installation, donc son Runtime est probablement plus ancien que ces Scripts. Extrayez le zip d’installation complet (AI-Companions-LLM, sur Nexus Mods) dans le dossier de Cyberpunk 2077, puis redémarrez le jeu.",
    ["The Runtime update from {from} to {to} was never applied, so some Runtime files are old. Extract the full install zip (AI-Companions-LLM, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "La mise à jour du Runtime de {from} à {to} n’a jamais été appliquée, donc certains fichiers du Runtime sont anciens. Extrayez le zip d’installation complet (AI-Companions-LLM, sur Nexus Mods) dans le dossier de Cyberpunk 2077, puis redémarrez le jeu.",
    ["Runtime files are old. Get the full install zip."] = "Les fichiers du Runtime sont anciens. Récupérez le ZIP complet.",
    ["Character unavailable in this game installation."] = "Personnage indisponible dans cette installation du jeu.",
    ["Message could not be delivered. Please try again."] = "Impossible de remettre le message. Réessayez.",
    ["The conversation service could not reply. Please try again."] = "Le service de conversation n’a pas pu répondre. Réessayez.",
    ["Voice conversation failed. Check your microphone and try again."] = "Échec de la conversation vocale. Vérifiez votre micro et réessayez.",
    ["Companions now and then pause, hesitate, laugh or sigh, as their personality would. It stays rare.\n\nOmniVoice can voice laughs and sighs; the other voices only add pauses.\n\nNot available with Convai’s cloud voice: choosing it turns this off, and turning this on switches the voice to Pocket."] = "Les compagnons marquent parfois une pause, hésitent, rient ou soupirent, selon leur personnalité. C’est rare.\n\nOmniVoice peut faire entendre des rires et des soupirs ; les autres voix ajoutent seulement des pauses.\n\nNon disponible avec la voix cloud de Convai : la choisir désactive cette option, et l’activer fait passer la voix sur Pocket.",
    ["For testing and bug reports; leave it off for normal play.\n\nShows routine popups, writes a movement trace in the mod’s runtime folder, logs gesture decisions and adds itself to support reports.\n\nFailures, preparation progress and joined notices stay visible when it is off."] = "Pour les tests et les rapports de bugs ; laissez désactivé pour une partie normale.\n\nAffiche les pop-ups courants, écrit une trace de mouvement dans le dossier du mod, journalise les gestes et s’ajoute aux rapports d’assistance.\n\nLes échecs, la progression de préparation et les avis d’arrivée restent visibles quand l’option est désactivée.",
    ["Pocket: the lightest, on your CPU, about 0.2 s to the first word.\n\nOmniVoice: richer, needs a capable GPU and its pack, 1 to 2.5 s.\n\nVoxtral: cloud voices with your Mistral key. The companions’ voice loads no local model; V’s typed lines follow V’s own voice setting.\n\nConvai: its own cloud voice. A voice that cannot run shows replies as text."] = "Pocket : le plus léger, sur votre processeur, premier mot en 0,2 s environ.\n\nOmniVoice : plus riche, nécessite un GPU performant et son pack, 1 à 2,5 s.\n\nVoxtral : cloud avec votre clé Mistral. Les voix des compagnons ne chargent aucun modèle local, et les répliques de V suivent le réglage de V.\n\nConvai : sa propre voix cloud. Une voix qui ne peut pas tourner affiche les réponses en texte.",
    ["The game’s own named characters, such as Judy, Jackie, Panam and Rogue, answer when you talk to them where they stand, with their own voice and memory.\n\nNothing else about them changes: they do not turn, move, gesture or follow, and stay quiet during scenes, quest conversations, fights and rides.\n\nTakes effect after you reload your save."] = "Les personnages nommés du jeu, comme Judy, Jackie, Panam et Rogue, répondent quand vous leur parlez où ils se trouvent, avec leur voix et leur mémoire.\n\nRien d’autre ne change : ils ne se retournent pas, ne bougent pas, ne font pas de gestes et ne vous suivent pas. Ils restent silencieux pendant les scènes, les conversations de quête, les combats et les trajets.\n\nPrend effet après le rechargement de la sauvegarde.",
    ["Mod Organizer 2. Files the mod creates go to its Overwrite folder; leave them there. Install the full install zip as one mod and update that mod with each new full install zip. Extract multilingual packs into that mod’s folder, not as new mods. Mention Mod Organizer 2 when you send a report."] = "Mod Organizer 2. Les fichiers créés par le mod vont dans son dossier Overwrite ; laissez-les là. Installez le zip d’installation complet comme un mod et mettez ce mod à jour avec chaque nouveau zip d’installation complet. Extrayez les packs multilingues dans le dossier de ce mod, pas comme de nouveaux mods. Mentionnez Mod Organizer 2 lorsque vous envoyez un rapport.",
    ["With a mod manager: remove the old Scripts and Runtime mods, then install the full install zip as one mod."] = "Avec un gestionnaire de mods : supprimez les anciens mods Scripts et Runtime, puis installez le zip d’installation complet comme un mod.",
    ["When something in the mod goes wrong, a short report goes to the developer.\n\nIt never holds keys, what you or the characters say, memories, audio or your Windows user name.\n\nIt holds the error, versions, settings, PC details (graphics card, processor, Windows, security software, drive, screen), mod names, setup check, reply timings and nearby log lines (for setup and script errors also the Cyber Engine Tweaks log)."] = "Si le mod plante, un court rapport part au développeur.\n\nIl ne contient jamais clés, conversations, souvenirs, audio ni nom d’utilisateur Windows.\n\nIl contient l’erreur, versions, réglages, PC (carte graphique, processeur, Windows, sécurité, disque, écran), mods, contrôle d’installation, temps de réponse et logs proches (pour l’installation et les scripts, aussi le log de Cyber Engine Tweaks).",
    ["Some Runtime files are from a newer update than this Runtime says. Extract the full install zip (AI-Companions-LLM, on Nexus Mods) into the Cyberpunk 2077 folder again. Then restart the game."] = "Certains fichiers du Runtime proviennent d’une mise à jour plus récente que celle indiquée par ce Runtime. Extrayez à nouveau le zip d’installation complet (AI-Companions-LLM, sur Nexus Mods) dans le dossier de Cyberpunk 2077. Puis redémarrez le jeu.",
    ["Multilingual pack ({code})"] = "Pack multilingue ({code})",
    ["PocketTTS model ({code})"] = "Modèle PocketTTS ({code})",
