    ["Move down"] = "Descendre",
    ["Delete rule {n}"] = "Supprimer règle {n}",
    ["Other versions of this rule"] = "Autres versions de cette règle",
    ["Leave a version empty to use the rule text."] = "Laissez une version vide pour utiliser le texte de la règle.",
    ["For a speaker with a reply length of its own"] = "Pour un locuteur ayant une longueur de réponse propre",
    ["For Mature content"] = "Pour adultes",
    ["Shipped: off"] = "D’origine : non",
    ["Shipped: the mod’s own limit"] = "D’origine : la limite propre au mod",
    ["before V’s words"] = "avant les mots de V",
    ["after V’s words"] = "après les mots de V",
    ["Repeat the “where you are” sentence right before V’s words"] = "Répéter la phrase « où vous êtes » juste avant les mots de V",
    ["The notes for this turn go"] = "Les notes pour ce tour vont",
    ["Output rules"] = "Règles de sortie",
    ["The numbered rules the model reads before every reply. Use {name} for the character’s name and {words} for the reply length of a speaker that has one."] = "Les règles numérotées que le modèle lit avant chaque réponse. Utilisez {name} pour le nom du personnage et {words} pour la longueur de réponse d’un locuteur qui en a une.",
    ["Example replies"] = "Exemples de réponses",
    ["Replies shown to the model after the rules. A small model may copy them word for word, so add none, or keep them short and plain."] = "Réponses montrées au modèle après les règles. Un petit modèle peut les recopier mot pour mot : n’en ajoutez aucune, ou gardez-les courtes et simples.",
    ["Add an example reply"] = "Ajouter un exemple",
    ["An example reply"] = "Un exemple de réponse",
    ["Example reply {n}"] = "Exemple de réponse {n}",
    ["Opening line"] = "Ligne d’ouverture",
    ["The first line of the character text. Use {name} for the character’s name."] = "La première ligne du texte du personnage. Utilisez {name} pour le nom du personnage.",
    ["The last thing the model reads before it answers. Use {name} for the character’s name and {words} for the reply length. The Mature setting adds its own clause after it."] = "Le dernier élément que lit le modèle avant de répondre. Utilisez {name} pour le nom du personnage et {words} pour la longueur de réponse. Le réglage pour adultes ajoute sa propre clause après.",
    ["Section headings"] = "Titres de section",
    ["The headings that mark each part of the prompt. Change the wording, not the order."] = "Les titres qui marquent chaque partie du prompt. Modifiez la formulation, pas l’ordre.",
    ["Layout"] = "Disposition",
    ["Where some notes go in the prompt."] = "Où certaines notes vont dans le prompt.",
    ["Sampling"] = "Échantillon",
    ["How freely the model words its reply. Leave a box empty to use the shipped value."] = "La liberté avec laquelle le modèle formule sa réponse. Laissez une case vide pour utiliser la valeur d’origine.",
    ["Length limits"] = "Limites de taille",
    ["Shorten what the model reads, which makes replies faster. The mod’s own limits still apply, so these can only make things shorter."] = "Raccourcit ce que lit le modèle, ce qui rend les réponses plus rapides. Les limites propres au mod restent appliquées, donc celles-ci ne peuvent que raccourcir.",
    ["Stop texts"] = "Textes d’arrêt",
    ["Mature layer"] = "Couche pour adultes",
    ["The wording added while Mature content is on. The mod picks the explicit or the suggestive version of a line from what the loaded model allows, so edit the version your model uses. An emptied box leaves that line out. The adults-only line and the hard limits are always added last and cannot be edited."] = "Les formulations ajoutées quand le Contenu pour adultes est activé. Le mod choisit la version explicite ou suggestive d’une réplique selon ce que permet le modèle chargé, alors modifiez la version que votre modèle utilise. Une case vidée retire cette réplique. La ligne réservée aux adultes et les limites strictes sont toujours ajoutées en dernier et ne peuvent pas être modifiées.",
    ["Speech line"] = "Réplique",
    ["Word bank"] = "Banque de mots",
    ["Romance line"] = "Réplique romantique",
    ["Closing clause"] = "Formule de fin",
    ["Tone line"] = "Ligne de ton",
