    ["Chinese"] = "Chinois",
    ["Choose one of the listed reply languages."] = "Choisissez l’une des langues de réponse proposées.",
    ["No speech was heard. Hold the talk key while you speak."] = "Aucune parole entendue. Maintenez la touche vocale enfoncée pendant que vous parlez.",
    ["Voice activation"] = "Activation vocale",
    ["Voice activation could not open the microphone. Check your Windows input device."] = "L'activation vocale n'a pas pu ouvrir le microphone. Vérifiez votre périphérique d'entrée Windows.",
    ["Voice input could not reach Convai. Hold the voice key again, or type."] = "L'entrée vocale n'a pas pu joindre Convai. Maintenez de nouveau la touche vocale enfoncée, ou tapez.",
    ["Talk without a key. While you face a character or a companion is near, the mod listens and answers when you pause for about a second.\n\nNever during the game’s own scenes or choices, or while a character speaks. Nothing leaves your PC unless speech is heard. Headphones work best, but a Bluetooth headset’s microphone drops it to call quality while this listens."] = "Parlez sans maintenir de touche. Face à un personnage ou si un compagnon est proche, le mod vous écoute et répond après une pause d'environ une seconde.\n\nJamais pendant les scènes ou choix de dialogue du jeu, ni pendant qu'un personnage parle. Rien ne quitte votre PC sans parole entendue. Le casque est recommandé ; un micro Bluetooth le passe en qualité d'appel pendant l'écoute.",
    ["Opening microphone…"] = "Ouverture du microphone…",
    ["Speak now"] = "Parlez maintenant",
    ["Type in the search box to find a model by name or record, for example “rita wheeler”. A part of a word is enough."] = "Saisissez du texte dans la zone de recherche pour trouver un modèle par son nom ou son enregistrement, par exemple « rita wheeler ». Une partie d’un mot suffit.",
    ["Content packs"] = "Paquets de contenu",
    ["Add-ons that change how the characters talk."] = "Modules complémentaires qui changent la façon dont les personnages parlent.",
    ["Content packs add rules after yours. You cannot edit them here: turn a pack off under Settings > Content packs in the game."] = "Les paquets de contenu ajoutent des règles après les vôtres. Vous ne pouvez pas les modifier ici : désactivez un paquet dans Paramètres > Paquets de contenu, dans le jeu.",
    ["From the content pack {name}"] = "Depuis le paquet de contenu {name}",
    ["Content packs that change this prompt: {names}. Your own changes stay on top of theirs, and Reset to default goes back to the pack’s wording."] = "Paquets de contenu qui modifient ce prompt : {names}. Vos propres modifications restent au-dessus des leurs, et Réinitialiser par défaut rétablit le texte du paquet.",
    ["Memory in use"] = "Souvenirs utilisés",
    ["Normal memory"] = "Souvenirs normaux",
    ["Forget memories clears only the memory shown here. The other memory stays as it is."] = "Effacer les souvenirs ne supprime que les souvenirs affichés ici. Les autres souvenirs restent tels quels.",
    ["This clears the memory in use: {memory}."] = "Cela efface les souvenirs utilisés : {memory}.",
    ["Backspace"] = "Retour arrière",
    ["Cancelled."] = "Annulé.",
    ["Caps lock"] = "Verr. Maj.",
    ["Choose a key or a controller button."] = "Choisissez une touche ou un bouton de manette.",
    ["Choose the keys and controller buttons for talking by voice or text, the group chats and the Companion Manager. They work at once."] = "Choisissez les touches et boutons de manette pour parler à la voix ou au texte, les discussions de groupe et la gestion des compagnons. Ils fonctionnent tout de suite.",
    ["Choose the keys and controller buttons for the mod’s actions. Press Set, then the key or button you want. Esc or B cancels. A change works at once, and the keys you set in Cyber Engine Tweaks keep working. Pick keys the game does not already use."] = "Choisissez les touches et boutons de manette pour les actions du mod. Appuyez sur Définir, puis sur la touche ou le bouton voulu. Esc ou B annule. Un changement prend effet tout de suite, et les touches définies dans Cyber Engine Tweaks restent actives. Choisissez des touches que le jeu n’utilise pas encore.",
    ["Controller {button}"] = "Manette : {button}",
    ["D-pad down"] = "Croix bas",
    ["D-pad left"] = "Croix gauche",
    ["D-pad right"] = "Croix droite",
    ["D-pad up"] = "Croix haut",
    ["Down arrow"] = "Flèche bas",
    ["End"] = "Fin",
    ["Enter"] = "Enter",
    ["Group text chat"] = "Groupe : texte",
    ["Group voice chat"] = "Groupe : voix",
    ["Hold it to talk to the characters around you at once, and let go to send. Facing nobody, you talk to the first member of your party and two others from it."] = "Maintenez-la pour parler à tous les personnages autour de vous en même temps, et relâchez pour envoyer. Si vous ne regardez personne, vous parlez au premier membre de votre groupe et à deux autres membres du groupe.",
    ["Hold it to talk to Johnny, the voice in your head, wherever you face, and let go to send. It needs Johnny in your head turned on in Settings."] = "Maintenez-la pour parler à Johnny, la voix dans votre tête, quel que soit l’endroit où vous regardez, et relâchez pour envoyer. Johnny dans votre tête doit être activé dans les Paramètres.",
    ["Hold the key or button while you speak and let go to send, like the Cyber Engine Tweaks talk key. Facing nobody, you talk to the first member of your party."] = "Maintenez la touche ou le bouton pendant que vous parlez, et relâchez pour envoyer, comme la touche de parole de Cyber Engine Tweaks. Si vous ne regardez personne, vous parlez au premier membre de votre groupe.",
    ["Home"] = "Début",
    ["Insert"] = "Inser",
    ["Key bindings"] = "Raccourcis",
    ["Key bindings need Codeware, and this game does not have it. Open Help for what is missing."] = "Les raccourcis demandent Codeware, que ce jeu n’a pas. Ouvrez l’Aide pour voir ce qui manque.",
    ["Key or button"] = "Touche ou bouton",
    ["Left arrow"] = "Flèche gauche",
    ["Menu"] = "Menu",
    ["No key was pressed, so nothing changed."] = "Aucune touche n’a été appuyée, donc rien n’a changé.",
    ["Not available"] = "Indisponible",
    ["Not set"] = "Non défini",
    ["Num lock"] = "Verr. Num",
    ["Page down"] = "Page suiv.",
    ["Page up"] = "Page préc.",
    ["Pause"] = "Pause",
    ["Press it, then the key or controller button you want. Esc or B cancels. It works at once."] = "Appuyez dessus, puis sur la touche ou le bouton de manette voulu. Esc ou B annule. Ça marche tout de suite.",
    ["Press it to open the Companion Manager while you play."] = "Appuyez dessus pour ouvrir la gestion des compagnons pendant que vous jouez.",
    ["Press it to type to the character you face. Facing nobody, you type to the first member of your party."] = "Appuyez dessus pour écrire au personnage devant vous. Si vous ne regardez personne, vous écrivez au premier membre de votre groupe.",
    ["Press it to type to Johnny, the voice in your head, wherever you face. It needs Johnny in your head turned on in Settings."] = "Appuyez dessus pour écrire à Johnny, la voix dans votre tête, quel que soit l’endroit où vous regardez. Johnny dans votre tête doit être activé dans les Paramètres.",
    ["Press it to type to the characters around you at once. Facing nobody, you type to the first member of your party and two others from it."] = "Appuyez dessus pour écrire à tous les personnages autour de vous en même temps. Si vous ne regardez personne, vous écrivez au premier membre de votre groupe et à deux autres membres du groupe.",
    ["Press the key or controller button for {action}. Esc or B cancels."] = "Appuyez sur la touche ou le bouton de manette pour {action}. Esc ou B annule.",
    ["Print screen"] = "Impr écran",
    ["Remove the key or button you set here."] = "Retirez la touche ou le bouton que vous avez défini ici.",
    ["Right arrow"] = "Flèche droite",
    ["Scroll lock"] = "Arrêt défil.",
    ["Space"] = "Espace",
    ["Tab"] = "Tab",
    ["Talk by text"] = "Parler par texte",
    ["Talk by voice"] = "Parler par la voix",
    ["Talk to Johnny by text"] = "Parler à Johnny par texte",
    ["Talk to Johnny by voice"] = "Parler à Johnny au micro",
    ["That key is already used for another action."] = "Cette touche est déjà utilisée pour une autre action.",
    ["The mod’s key bindings could not be loaded. Open Help for what is wrong."] = "Les raccourcis du mod n’ont pas pu être chargés. Ouvrez l’Aide pour voir le problème.",
    ["The mod’s scripts did not load, so no key can be set. Open Help for what is wrong."] = "Les scripts du mod ne se sont pas chargés, donc aucune touche ne peut être définie. Ouvrez l’Aide pour voir le problème.",
    ["Up arrow"] = "Flèche haut",
    ["View"] = "Affichage",
    ["{action} cleared."] = "{action} effacé.",
    ["{action} is set to {key}."] = "{action} est défini sur {key}.",
    ["{key} is already used for {other}. Choose another."] = "{key} est déjà utilisé pour {other}. Choisissez-en un autre.",
    ["10 minutes"] = "10 minutes",
    ["2 minutes"] = "2 minutes",
    ["5 minutes"] = "5 minutes",
    ["Cancel this meeting. She is not told."] = "Annuler le rendez-vous, sans la prévenir.",
    ["Car"] = "Voiture",
    ["Choose how long she waits."] = "Choisis combien de temps elle attend.",
    ["Choose how she arrives."] = "Choisis comment elle arrive.",
    ["Choose one of the listed options."] = "Choisis une des options proposées.",
    ["Choose when she arrives."] = "Choisis quand elle arrive.",
    ["Companions travel to you when you invite them: they walk or drive in, text you, wait, and remember if you never come.\n\nOff by default."] = "Quand tu les invites, les compagnons viennent à pied ou en voiture, t’écrivent, attendent et s’en souviennent si tu ne viens pas.\n\nDésactivé par défaut.",
    ["Fine. Call me when you know what you want."] = "D’accord. Rappelle-moi quand tu sauras ce que tu veux.",
    ["How long she waits"] = "Combien de temps elle attend",
    ["How long she waits for you after arriving right now. After a timed arrival she waits as long as the delay you chose. The wait stops while you are in a fight, a scene or a menu."] = "Combien de temps elle t’attend à son arrivée immédiate. Après une arrivée programmée, elle attend autant que le délai choisi. L’attente s’arrête pendant un combat, une scène ou un menu.",
    ["How she arrives"] = "Comment elle arrive",
    ["I waited {minutes} minutes at {place} and you never showed. Forget it."] = "J’ai attendu {minutes} minutes à {place} et tu n’es jamais venu. Laisse tomber.",
    ["I'm here at {place}. Where are you?"] = "Je suis là, à {place}. Tu es où ?",
    ["Immersive invitations"] = "Invitations immersives",
    ["In 10 minutes"] = "Dans 10 min",
    ["In 2 minutes"] = "Dans 2 min",
    ["In 5 minutes"] = "Dans 5 min",
    ["Invite a companion and she really travels to you: she appears out of sight, walks or drives in, texts you when she is there and waits for you."] = "Invite un compagnon et elle vient vraiment à toi : elle apparaît hors de vue, arrive à pied ou en voiture, t’écrit quand elle est là et t’attend.",
    ["Meet at my waypoint when I ask"] = "Rejoindre mon point sur demande",
    ["Off: Invite brings a companion to your side at once.\n\nOn: a companion you invite, by the Invite button, the Contacts tab or a text, travels to you and arrives after the time you choose here. She texts you when she is there, waits, and leaves angry (and remembers it) if you never come."] = "Désactivé : Inviter amène un compagnon à tes côtés immédiatement.\n\nActivé : un compagnon que tu invites, par le bouton Inviter, l’onglet Contacts ou un message, se rend à toi et arrive après le délai choisi ici. Elle t’écrit quand elle est là, attend et repart en colère (et s’en souvient) si tu ne viens jamais.",
    ["Right now"] = "Maintenant",
    ["Right now: she is on her way as soon as she is ready.\n\nIn 2, 5 or 10 minutes: real minutes of play, so she arrives at that time. She then waits as long as that delay."] = "Maintenant : elle se met en route dès qu’elle est prête.\n\nDans 2, 5 ou 10 minutes : de vraies minutes de jeu, elle arrive donc à cette heure-là. Elle attend ensuite autant que ce délai.",
    ["She texts you"] = "Elle t’écrit",
    ["She texts you when she arrives, when you cancel and when she gives up. Off: no texts (she still remembers being stood up)."] = "Elle t’écrit à son arrivée, quand tu annules et quand elle abandonne. Désactivé : aucun message (elle se souvient quand même du lapin).",
    ["Something came up and I can't make it. Sorry."] = "Un imprévu m’empêche de venir. Désolée.",
    ["Walk"] = "À pied",
    ["Walk: she appears out of your sight and walks to you.\n\nCar: when a road is near she drives in, stops on the road, gets out and walks the rest. Without a road she walks. The car stays near for a ride, and is removed when she leaves your group or you both go far from it."] = "À pied : elle apparaît hors de vue et marche jusqu’à toi.\n\nVoiture : si une route est proche, elle s’y arrête en voiture, descend et finit à pied. Sans route, elle marche. La voiture reste près de toi pour le trajet et disparaît quand elle quitte ton groupe ou que vous vous éloignez tous les deux.",
    ["When she arrives"] = "Quand elle arrive",
    ["When you ask her to come to your waypoint and a map pin is set, she goes there and says so. Off: she always comes to where you are."] = "Si tu lui demandes de venir à ton point et qu’un repère est posé, elle y va et le dit. Désactivé : elle vient là où tu es.",
    ["Your position cannot be read yet."] = "Ta position ne peut pas encore être lue.",
    ["on her way"] = "en chemin",
    ["the meeting spot"] = "le point de rendez-vous",
    ["waiting at {place}"] = "attend à {place}",
    ["{name} is already on the way."] = "{name} est déjà en chemin.",
    ["{name} is on her way."] = "{name} est en chemin.",
    ["{name} is on her way. About {minutes} minutes."] = "{name} est en chemin. Environ {minutes} minutes.",
    ["{name} · {state}"] = "{name} · {state}",
    ["{name}: Good to see you. Let us go."] = "{name} : Ravie de te voir. On y va.",
    ["Corpo Plaza"] = "Corpo Plaza",
    ["Heywood Glen"] = "Heywood Glen",
    ["Megabuilding H10"] = "Megabuilding H10",
    ["Move out"] = "Faire déménager",
    ["That companion is not available."] = "Ce compagnon n’est pas disponible.",
    ["Watson Northside"] = "Watson Northside",
    ["Westbrook Japantown"] = "Westbrook Japantown",
    ["You do not have that apartment."] = "Vous n’avez pas cet appartement.",
    ["at home"] = "à la maison",
    ["out"] = "dehors",
    ["with you"] = "avec vous",
    ["{count} more housemates"] = "{count} colocataires de plus",
    ["{name} has moved out."] = "{name} a déménagé.",
    ["{name} is back at home."] = "{name} est de retour à la maison.",
    ["{name} joins you."] = "{name} vous rejoint.",
    ["{name} moves into {apartment}."] = "{name} emménage à {apartment}.",
    ["{name} now lives in {apartment} and stays in your party until sent home."] = "{name} habite désormais à {apartment} et reste dans ton groupe jusqu'à son retour à la maison.",
    ["{name} stops living at your place. She stays as she is otherwise."] = "{name} ne vit plus chez vous. Le reste ne change pas.",
    ["{name} · lives in {apartment} · {state}"] = "{name} · habite {apartment} · {state}",
    ["Companions change outfits"] = "Compagnons changent de tenue",
    ["Your party’s companions change outfits now and then: another look by day and by night, and casual clothes at home, where the character has them.\n\nOnly out of your sight, never in front of you, and only for your party’s own copies, never the game’s own characters. Turning this off keeps what they wear now."] = "Les compagnons de votre groupe changent de tenue de temps en temps : un autre look le jour et la nuit, et des vêtements décontractés à la maison, quand le personnage en possède.\n\nUniquement hors de votre vue, jamais devant vous, et seulement pour les copies propres à votre groupe, jamais pour les personnages du jeu. Désactiver cette option les laisse dans la tenue qu’ils portent à ce moment-là.",
    ["Choose how often companions speak up."] = "Choisissez à quelle fréquence les compagnons prennent la parole.",
    ["Companions speak up"] = "Les compagnons prennent la parole",
    ["How V is doing according to other mods, when they are installed: Dark Future’s tiredness, hunger, thirst, nerve and addictions, for example. Also what V visibly wears while an Equipment-EX outfit is on, so characters describe the outfit and not the clothes it hides.\n\nOff by default. Off: it is not sent, and nothing is read from those mods."] = "Comment va V selon les autres mods, s’ils sont installés : par exemple la fatigue, la faim, la soif, les nerfs et les addictions de Dark Future. Aussi ce que V porte visiblement tant qu’une tenue d’Equipment-EX est active, pour que les personnages décrivent la tenue et non les vêtements qu’elle cache.\n\nDésactivé par défaut. Désactivé : rien n’est envoyé, et ces mods ne sont pas lus.",
    ["How long it has been since V last talked to this character, in the game and in real days: since last night, or days ago. Said only when the gap is long enough to matter, and not again in the same conversation.\n\nOff: it is not sent, and the mod stops reading the game clock for it."] = "Depuis combien de temps V a parlé à ce personnage pour la dernière fois, dans le jeu et en jours réels : depuis hier soir, ou il y a des jours. Ce n’est dit que si l’écart est assez long pour compter, et pas deux fois dans la même conversation.\n\nDésactivé : rien n’est envoyé, et le mod cesse de lire l’horloge du jeu pour cela.",
    ["Music and TV"] = "Musique et TV",
    ["Other mods’ state"] = "État des autres mods",
    ["Speaks up normally"] = "Prend la parole normalement",
    ["The song playing on the car radio while V rides with the character, or on V’s pocket radio, and what is on a TV near V.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "La chanson diffusée à la radio de la voiture quand V roule avec le personnage, ou sur la radio de poche de V, et ce qui passe sur une TV près de V.\n\nDésactivé : rien n’est envoyé, et le mod cesse de le lire dans le jeu.",
    ["Time since last talk"] = "Temps depuis la dernière discussion",
    ["Companions in your party sometimes start talking on their own, at a calm moment or after a scene. With two or more near you, it is often a short chat between up to three of them, and you can join in by talking. Never during fights, scenes, calls or menus.\n\nRarely: about 2 an hour. Normally: about 4. Often (the default): about 6.\n\nWith Johnny speaking up too, the rates add up and they take turns."] = "Les compagnons parlent parfois d’eux-mêmes, lors d’un moment calme ou après une scène. À deux ou plus près de vous, souvent un court échange entre trois au plus, où vous pouvez intervenir. Jamais en combat, scène, appel ou menu.\n\nRarement : environ 2 par heure de jeu. Normalement : environ 4. Souvent (par défaut) : environ 6.\n\nQuand Johnny parle aussi, les deux fréquences s’additionnent et ils se relaient.",
    ["Johnny Silverhand answers the Talk to Johnny keys, as the voice in V’s head, once the story has him there. Give Talk to Johnny a key on the Key bindings page: none is set by default.\n\nOn: he answers when you talk to him. Rarely: he also speaks up on his own, about 2 an hour. Normally: about 4. Often: about 6.\n\nWith companions speaking up too, the rates add up and they take turns."] = "Johnny Silverhand répond aux touches Parler à Johnny, comme la voix dans la tête de V, dès que le récit l’y place. Attribuez une touche à Parler à Johnny sur la page Raccourcis : aucune n’est définie par défaut.\n\nActivé : il répond quand on lui parle. Rarement : de lui-même, environ 2 fois par heure. Normalement : environ 4. Souvent : environ 6.\n\nAvec les compagnons, les fréquences s’additionnent et ils se relaient.",
    ["Choose which live game info the characters are told, such as location, time, weather, company, health, money, gear, quests, music and TV, and other mods’ state.\n\nAll on by default except other mods’ state, which is off. An off kind is not sent to any conversation provider."] = "Choisissez les infos de jeu en direct transmises aux personnages, comme le lieu, l’heure, la météo, les compagnons, la santé, l’argent, l’équipement, les quêtes, la musique et TV, et l’état des autres mods.\n\nTout est activé par défaut, sauf l’état des autres mods, qui est désactivé. Un type désactivé n’est envoyé à aucun fournisseur de conversation.",
    ["Housemates"] = "Colocataires",
    ["Housemates talk to each other"] = "Les colocataires se parlent",
    ["When two or more housemates are home with you, they talk to each other now and then."] = "Quand deux colocataires ou plus sont à la maison avec toi, ils se parlent de temps en temps.",
    ["Characters you tell they can stay at your place move into your apartments and live there."] = "Les personnages à qui tu dis qu’ils peuvent rester chez toi emménagent dans tes appartements et y vivent.",
    ["Characters you tell they can stay at your place move into your apartments and live there.\n\nOff by default."] = "Les personnages à qui tu dis qu’ils peuvent rester chez toi emménagent dans tes appartements et y vivent.\n\nDésactivé par défaut.",
    ["On: characters you tell they can stay at your place move into your apartments and live there, and you can call them along.\n\nOff: nothing of this runs. Turning it off removes them from your apartments but remembers who lived there, so turning it on brings them back."] = "Activé : les personnages à qui tu dis qu’ils peuvent rester chez toi emménagent dans tes appartements et y vivent, et tu peux les emmener avec toi.\n\nDésactivé : rien de tout cela ne tourne. En désactivant, ils quittent tes appartements, mais on se souvient de qui y vivait, donc ils reviennent quand tu réactives.",
    ["OmniVoice Python"] = "OmniVoice Python",
    ["OmniVoice’s code could not load in it"] = "le code d'OmniVoice n'a pas pu être chargé",
    ["PyTorch is not installed in it"] = "PyTorch n'est pas installé",
    ["Your own Python (omni-python.txt) is being tested. Open this page again in a minute."] = "Votre propre Python (omni-python.txt) est en cours de test. Rouvrez cette page dans une minute.",
    ["Your own Python (omni-python.txt) is tested when OmniVoice starts or when this page checks again."] = "Votre propre Python (omni-python.txt) est testé quand OmniVoice démarre ou quand cette page revérifie.",
    ["Your own Python (omni-python.txt) runs OmniVoice with {backend} on {card}. Experimental."] = "Votre propre Python (omni-python.txt) exécute OmniVoice avec {backend} sur {card}. Expérimental.",
    ["Your own Python (omni-python.txt) was not used: {reason}. OmniVoice uses the Runtime’s Python, which needs an NVIDIA card."] = "Votre propre Python (omni-python.txt) n'a pas été utilisé : {reason}. OmniVoice utilise le Python du Runtime, qui nécessite une carte NVIDIA.",
    ["a test on the graphics card failed"] = "un test sur la carte graphique a échoué",
    ["it did not start or did not answer in time"] = "il n'a pas démarré ou n'a pas répondu à temps",
    ["its PyTorch finds no graphics card (no CUDA or ROCm)"] = "son PyTorch ne trouve pas de carte graphique (pas de CUDA ou ROCm)",
    ["the OmniVoice pack is not installed"] = "le paquet OmniVoice n'est pas installé",
    ["the file does not name a python.exe that exists"] = "le fichier ne spécifie pas un python.exe existant",
    ["the module {module} is missing in it"] = "le module {module} y manque",
    ["1 minute"] = "1 minute",
    ["2 people"] = "2 personnes",
    ["3 people"] = "3 personnes",
    ["4 people"] = "4 personnes",
    ["Every character who lives at your place moves out at once, from every apartment. Party members who do not live there are not touched. A housemate who is with you stays in your party."] = "Tous les personnages qui vivent chez toi déménagent en même temps, de tous les appartements. Les membres du groupe qui n'y vivent pas ne sont pas touchés. Une colocataire avec toi reste dans le groupe.",
    ["Evict"] = "Expulser",
    ["Evict all housemates"] = "Expulser tous les colocataires",
    ["Housemates in one chat"] = "Colocataires dans un chat",
    ["Housemates moved out: {count}"] = "Colocataires ont déménagé : {count}",
    ["How long the housemates stay quiet after a chat before they may start another. The Companions speak up setting still limits how many chats come in an hour."] = "Combien de temps les colocataires restent silencieux après un chat avant de pouvoir en commencer un autre. Le paramètre Les compagnons prennent la parole limite toujours le nombre de chats qui arrivent en une heure.",
    ["How many housemates join one chat when that many are home near each other. They speak one at a time. With fewer at home, the chat is as big as it can be."] = "Combien de colocataires participent à un chat quand ce nombre est à la maison près l'un de l'autre. Ils parlent un à la fois. Avec moins à la maison, le chat est aussi grand que possible.",
    ["Move-in apartment"] = "Appartement d'emménagement",
    ["Nobody lives at your place."] = "Personne ne vit chez toi.",
    ["Pause between chats"] = "Pause entre les chats",
    ["Where a character moves in when you say she can stay but name no apartment and you are not standing in one of yours.\n\nAsk me: she asks which one. Otherwise she takes the apartment you pick here. Only the apartments you own are listed."] = "Où un personnage emménage quand tu dis qu'elle peut rester mais que tu ne nommes pas d'appartement et que tu ne te tiens pas dans l'un des tiens.\n\nDemande-moi: elle demande lequel. Sinon, elle prend l'appartement que tu choisis ici. Seuls les appartements que tu possèdes sont énumérés.",
    ["Ask me"] = "Demande-moi",
    ["Could not start"] = "Impossible de démarrer",
    ["Did not start"] = "Non démarré",
    ["If the folder is there, the newest log in red4ext/logs says why RED4ext did not load it: an antivirus that removed a file, or a missing Visual C++ runtime."] = "Si le dossier est là, le log le plus récent dans red4ext/logs indique pourquoi RED4ext ne l’a pas chargé : un antivirus a supprimé un fichier, ou le Visual C++ runtime manque.",
    ["Load a save first. A key can be set only while a game is loaded."] = "Chargez d’abord une sauvegarde. Une touche ne peut être définie que lorsqu’une partie est chargée.",
    ["No key press reached the mod, so nothing changed. If keys do not arrive from this menu, set the key in Cyber Engine Tweaks’ Bindings: it works the same."] = "Aucune touche n’est parvenue au mod, donc rien n’a changé. Si les touches n’arrivent pas depuis ce menu, définissez la touche dans les raccourcis de Cyber Engine Tweaks : cela fonctionne de la même façon.",
    ["Runtime incomplete"] = "Runtime incomplet",
    ["Runtime not loaded"] = "Runtime non chargé",
    ["Service not running ({reason})"] = "Service non lancé ({reason})",
    ["The Runtime’s plugin is loaded, but the conversation service left no trace in this session. launcher.log in red4ext/plugins/AiNpcCyberpunkCode says why: launcher.ini switched off, Node missing, or Node blocked by a security program. Fix that, then restart the game."] = "Le plugin du Runtime est chargé, mais le service de conversation n’a laissé aucune trace dans cette session. launcher.log dans red4ext/plugins/AiNpcCyberpunkCode indique pourquoi : launcher.ini désactivé, Node absent ou Node bloqué par un programme de sécurité. Corrigez cela, puis redémarrez le jeu.",
    ["The conversation service cannot see this mod’s folder in the game: a mod manager’s virtual folders, or a folder it may not read. Extract the Runtime straight into the Cyberpunk 2077 folder, or start the game from the mod manager that holds the Runtime."] = "Le service de conversation ne voit pas le dossier de ce mod dans le jeu : dossiers virtuels d’un gestionnaire de mods, ou dossier qu’il n’a pas le droit de lire. Extrayez le Runtime directement dans le dossier de Cyberpunk 2077, ou lancez le jeu depuis le gestionnaire de mods qui contient le Runtime.",
    ["The conversation service was started and never reported back. A security program probably stopped it at once, or Node cannot run on this PC. Allow red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe in your security program, then restart the game."] = "Le service de conversation a été lancé mais n’a jamais répondu. Un programme de sécurité l’a probablement arrêté aussitôt, ou Node ne peut pas tourner sur ce PC. Autorisez red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe dans votre programme de sécurité, puis redémarrez le jeu.",
    ["Windows would not let the game start the conversation service (error {error}). A security program may be blocking node.exe in red4ext/plugins/AiNpcCyberpunkMod/app/node: allow it, then restart the game."] = "Windows n’a pas permis au jeu de lancer le service de conversation (erreur {error}). Un programme de sécurité bloque peut-être node.exe dans red4ext/plugins/AiNpcCyberpunkMod/app/node : autorisez-le, puis redémarrez le jeu.",
    ["Add a server address first."] = "Ajoutez d’abord une adresse de serveur.",
    ["Asks the server three times who it is and shows whether it is reachable, how long it takes to answer and its version. It sends no speech."] = "Demande trois fois au serveur qui il est et indique s’il est joignable, le temps qu’il met à répondre et sa version. Aucune voix n’est envoyée.",
    ["Connected. The server speaks with {voice}."] = "Connecté. Le serveur parle avec {voice}.",
    ["Custom voices"] = "Voix personnalisées",
    ["Deletes the saved server address. Remote OmniVoice needs one to speak."] = "Supprime l’adresse de serveur enregistrée. OmniVoice distant en a besoin pour parler.",
    ["It answers in {ms} ms."] = "Répond en {ms} ms.",
    ["Its voice runs on {device}."] = "Sa voix tourne sur {device}.",
    ["Loading"] = "Chargement",
    ["Not connected. Replies show as text until the server answers."] = "Non connecté. Les réponses s’affichent en texte tant que le serveur ne répond pas.",
    ["Nothing answered at that address. Check that the server is running, that the address and port are right and that both PCs are on the same network. A server started with its default only listens on its own PC: start it with the listen address 0.0.0.0."] = "Aucune réponse à cette adresse. Vérifiez que le serveur est lancé, que l’adresse et le port sont corrects et que les deux PC sont sur le même réseau. Un serveur lancé avec sa configuration par défaut n’écoute que sur son propre PC : démarrez-le avec l’adresse d’écoute 0.0.0.0.",
    ["Off. OmniVoice runs on this PC."] = "Désactivé. OmniVoice tourne sur ce PC.",
    ["On, but no server address is saved. OmniVoice cannot speak yet."] = "Activé, mais aucune adresse de serveur n’est enregistrée. OmniVoice ne peut pas encore parler.",
    ["On, but no server address is saved. Pocket is used until you add one."] = "Activé, mais aucune adresse de serveur n’est enregistrée. Pocket est utilisé tant que vous n’en ajoutez pas une.",
    ["On, but no server address is saved. The server is not used yet."] = "Activé, mais aucune adresse de serveur n’est enregistrée. Le serveur n’est pas encore utilisé.",
    ["On, but a cloud voice is chosen under Companion voices, so the server is not used."] = "Activé, mais une voix cloud est choisie dans Voix des compagnons, donc le serveur n’est pas utilisé.",
    ["On. Waiting for the conversation service."] = "Activé. En attente du service de conversation.",
    ["Paste address"] = "Coller l’adresse",
    ["Remote OmniVoice"] = "OmniVoice distant",
    ["Render the voices on another PC or graphics card that runs the OmniVoice server, so this PC keeps its frames.\n\nTurn it on, press Apply and add the server address below. The server then speaks for every Pocket or OmniVoice choice under Companion voices; a cloud voice stays as chosen. If it cannot be reached, replies show as text and the mod retries every few seconds."] = "Générer les voix sur un autre PC ou une autre carte graphique avec le serveur OmniVoice, pour que ce PC conserve sa fluidité.\n\nActivez, appuyez sur Appliquer et ajoutez l’adresse du serveur ci-dessous. Le serveur parle pour chaque choix Pocket ou OmniVoice de Voix des compagnons ; une voix cloud reste telle quelle. Injoignable : réponses en texte, nouvel essai toutes les quelques secondes.",
    ["Render the OmniVoice voices on another PC or graphics card that runs the OmniVoice server."] = "Générer les voix OmniVoice sur un autre PC ou une autre carte graphique qui exécute le serveur OmniVoice.",
    ["Render Pocket and OmniVoice voices on another PC or graphics card: the on/off switch, the server address and a connection test. It works whichever of those voices is chosen above."] = "Générer les voix Pocket et OmniVoice sur un autre PC ou une autre carte graphique : l’interrupteur marche/arrêt, l’adresse du serveur et un test de connexion. Cela marche quelle que soit celle de ces voix choisie plus haut.",
    ["Server address"] = "Adresse du serveur",
    ["Something answered, but it is not the OmniVoice server. Check the port."] = "Quelque chose a répondu, mais ce n’est pas le serveur OmniVoice. Vérifiez le port.",
    ["Start the OmniVoice server on the other PC. Its window shows the address to use, for example 192.168.1.20:8765. Copy it, then choose Paste address. It is read from the clipboard once and saved on this computer.\n\nOn the same PC use 127.0.0.1:8765. You can also write address=192.168.1.20:8765 in player-remote-omnivoice.txt in the conversation service folder.\n\nNothing is sent to it until Remote OmniVoice is on and OmniVoice is chosen, or you press Test."] = "Lancez le serveur OmniVoice sur l’autre PC. Sa fenêtre affiche l’adresse à utiliser, par exemple 192.168.1.20:8765. Copiez-la, puis choisissez Coller l’adresse. Elle est lue une seule fois dans le presse-papiers et enregistrée sur cet ordinateur.\n\nSur le même PC, utilisez 127.0.0.1:8765. Vous pouvez aussi écrire address=192.168.1.20:8765 dans player-remote-omnivoice.txt, dans le dossier du service de conversation.\n\nRien n’est envoyé tant qu’OmniVoice distant n’est pas activé et qu’OmniVoice n’est pas choisi, ou que vous n’appuyez pas sur Tester.",
    ["Status"] = "État",
    ["The OmniVoice server cannot be reached. Replies show as text until it answers. The mod asks it again every few seconds."] = "Le serveur OmniVoice est injoignable. Les réponses s’affichent en texte tant qu’il ne répond pas. Le mod le recontacte toutes les quelques secondes.",
    ["The clipboard does not hold a server address."] = "Le presse-papiers ne contient pas d’adresse de serveur.",
    ["The clipboard is empty. Copy the address first."] = "Le presse-papiers est vide. Copiez d’abord l’adresse.",
    ["The port must be a number from 1 to 65535."] = "Le port doit être un nombre compris entre 1 et 65535.",
    ["The server address was removed."] = "L’adresse du serveur a été supprimée.",
    ["The server answered but could not load its voice. Its window says why."] = "Le serveur a répondu, mais n’a pas pu charger sa voix. Sa fenêtre indique la raison.",
    ["The server answered but is still loading its voice. Try again in a minute."] = "Le serveur a répondu, mais charge encore sa voix. Réessayez dans une minute.",
    ["The server is another version. Use the server folder and the mod from the same release."] = "Le serveur est une autre version. Utilisez le dossier du serveur et le mod de la même version.",
    ["The server is ready."] = "Le serveur est prêt.",
    ["The server refused the request."] = "Le serveur a refusé la demande.",
    ["The server took too long to answer."] = "Le serveur a mis trop de temps à répondre.",
    ["Use the address only: no user name, no path, no #."] = "Indiquez seulement l’adresse : pas de nom d’utilisateur, pas de chemin, pas de #.",
    ["Use the address the server window shows, such as 192.168.1.20:8765, without https://."] = "Indiquez l’adresse affichée par la fenêtre du serveur, comme 192.168.1.20:8765, sans https://.",
    ["Waiting for the server to answer…"] = "En attente de la réponse du serveur…",
    ["Whether the server is in use right now. It is checked when a voice is needed and again every few seconds after a failure, never while you play."] = "Indique si le serveur est utilisé en ce moment. Il est vérifié lorsqu’une voix est nécessaire, puis toutes les quelques secondes après un échec, jamais pendant que vous jouez.",
    ["Your own character, made in the character editor."] = "Votre propre personnage, créé dans l’éditeur de personnages.",
    ["Build for your game"] = "Build pour votre jeu",
    ["Your game is {game} but the Runtime is the one for game {runtime}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over this one, then restart the game."] = "Votre jeu est {game}, mais le Runtime est celui du jeu {runtime}. Téléchargez le zip d’installation complet pour le jeu {game} depuis la page du mod sur Nexus Mods (fichier principal pour le jeu 2.5, fichier optionnel pour le jeu 2.31), extrayez-le dans le dossier de Cyberpunk 2077 par-dessus l’actuel, puis redémarrez le jeu.",
    ["Your game is {game} but the Scripts are the build for game {scripts}. Get the update zip for game {game} from the mod’s Nexus Mods page (the update file is for game 2.5, the optional update file for game 2.31) and install it over these, then restart the game."] = "Votre jeu est {game}, mais les Scripts sont la build pour le jeu {scripts}. Téléchargez le zip de mise à jour pour le jeu {game} depuis la page du mod sur Nexus Mods (la mise à jour est pour le jeu 2.5, la mise à jour optionnelle pour le jeu 2.31), installez-le par-dessus les actuels, puis redémarrez le jeu.",
    ["Your game is {game} but the Scripts and the Runtime are the build for game {scripts}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over these, then restart the game."] = "Votre jeu est {game}, mais les Scripts et le Runtime sont la build pour le jeu {scripts}. Téléchargez le zip d’installation complet pour le jeu {game} depuis la page du mod sur Nexus Mods (fichier principal pour le jeu 2.5, fichier optionnel pour le jeu 2.31), extrayez-le dans le dossier de Cyberpunk 2077 par-dessus les actuels, puis redémarrez le jeu.",
    ["The Scripts are the build for game {scripts} but the Runtime is the build for game {runtime}, and the game version matches neither. Extract the full install zip made for the same game as yours (from Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Les Scripts sont la build pour le jeu {scripts}, mais le Runtime est la build pour le jeu {runtime}, et la version du jeu ne correspond à aucun des deux. Extrayez le zip d’installation complet prévu pour le même jeu que le vôtre (depuis Nexus Mods) dans le dossier de Cyberpunk 2077, puis redémarrez le jeu.",
    ["The Runtime is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Runtime pour le jeu {other}, le vôtre est {game}. Récupérez le ZIP complet pour {game}.",
    ["The Scripts are for game {other}, yours is {game}. Get the update zip for {game}."] = "Scripts pour le jeu {other}, le vôtre est {game}. Récupérez le Update-ZIP pour {game}.",
    ["This mod is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Mod pour {other}, le vôtre est {game}. Prenez le ZIP complet pour {game}.",
    ["Scripts are for game {scripts}, Runtime for {runtime}. They must match. See Help in Settings."] = "Scripts {scripts}, Runtime {runtime}. Doivent correspondre : voir Aide dans Paramètres.",
    ["Choose one of the listed microphones."] = "Choisissez l'un des microphones de la liste.",
    ["Microphone"] = "Microphone",
    ["The microphone you chose in Settings ({chosen}) is not connected, so the Windows default input is used: {name}."] = "Le microphone choisi dans les Paramètres ({chosen}) n'est pas connecté, l'entrée par défaut de Windows est donc utilisée : {name}.",
    ["The microphone you chose in Settings is not connected, so the Windows default input is used."] = "Le microphone choisi dans les Paramètres n'est pas connecté, l'entrée par défaut de Windows est donc utilisée.",
    ["Windows default"] = "Par défaut (Windows)",
    ["not connected"] = "non connecté",
    ["{name}, chosen in Settings > Voices."] = "{name}, choisi dans Paramètres > Voix.",
    ["{name}, the Windows default input. Settings > Voices > Microphone chooses another."] = "{name}, l'entrée par défaut de Windows. Paramètres > Voix > Microphone permet d'en choisir une autre.",
    ["Revenge ambushes"] = "Embuscades de vengeance",
    ["Speak dialogue choices"] = "Dire les choix de dialogue",
    ["Say a dialogue choice to pick it: its words, a part of them, or its number (\"two\", \"the last one\"). If nothing fits clearly, nothing is picked. No character answers.\n\nPresses the arrow keys and Enter, so the game must be in front. Needs speech recognition on this PC. Headphones work best."] = "Dites un choix de dialogue pour le choisir : ses mots, une partie de ces mots ou son numéro (\"deux\", \"le dernier\"). Si rien ne correspond clairement, rien n’est choisi. Aucun personnage ne répond.\n\nAppuie sur les flèches et Enter, donc le jeu doit être au premier plan. Nécessite la reconnaissance vocale sur ce PC. Le casque donne les meilleurs résultats.",
    ["No option matched. Say its number."] = "Aucun choix ne correspond. Dites son numéro.",
    ["Two options fit. Say its number."] = "Deux choix correspondent. Dites son numéro.",
    ["Speaking a choice needs speech recognition on this PC."] = "Dire un choix nécessite la reconnaissance vocale sur ce PC.",
    ["AMD’s ROCm PyTorch does not support this card yet."] = "Le PyTorch ROCm d’AMD ne prend pas encore en charge cette carte.",
    ["Another setup is already running. Wait for it to finish."] = "Une autre configuration est déjà en cours. Attends qu’elle se termine.",
    ["Cancelled"] = "Annulé",
    ["Cancelling…"] = "Annulation…",
    ["Checking your card…"] = "Vérification de ta carte…",
    ["Downloading {done} of {total} MB ({percent}%)"] = "Téléchargement de {done} sur {total} MB ({percent}%)",
    ["Downloading…"] = "Téléchargement…",
    ["Experimental. Pocket speaks until it is ready. A local voice never switches to a cloud voice."] = "Expérimental. Pocket parle en attendant qu’il soit prêt. Une voix locale ne passe jamais à une voix cloud.",
    ["Frees about {disk} GB."] = "Libère environ {disk} GB.",
    ["Frees the space it took."] = "Libère l’espace qu’il occupait.",
    ["Install"] = "Installer",
    ["Installed"] = "Installé",
    ["Installed. OmniVoice uses it when it starts."] = "Installé. OmniVoice l’utilise au démarrage.",
    ["It is kept in the mod’s data folder on drive C:."] = "Il est conservé dans le dossier de données du mod sur le lecteur C:.",
    ["It runs in the background while you play. The game keeps running and nothing else changes."] = "Il tourne en arrière-plan pendant que tu joues. Le jeu continue de tourner et rien d’autre ne change.",
    ["It takes about {disk} GB on drive C: in the mod’s data folder."] = "Il prend environ {disk} GB sur le lecteur C:, dans le dossier de données du mod.",
    ["MIOpen convolutions (AMD)"] = "Convolutions MIOpen (AMD)",
    ["Not available on this PC. It needs an AMD Radeon card and the OmniVoice pack."] = "Non disponible sur ce PC. Il faut une carte AMD Radeon et le pack OmniVoice.",
    ["OmniVoice for AMD"] = "OmniVoice pour AMD",
    ["OmniVoice on AMD: set up first"] = "OmniVoice sur AMD : configure-le d’abord",
    ["OmniVoice then no longer starts on this card until it is set up again."] = "OmniVoice ne démarre alors plus sur cette carte tant qu’elle n’est pas reconfigurée.",
    ["On: AMD’s MIOpen runs the convolutions, with MIOPEN_FIND_MODE=2 and MIOPEN_FIND_ENFORCE=1. Off: PyTorch’s own convolutions. Which is faster depends on your card and driver: if voices are slow or stop part-way, try the other one. AMD cards only. OmniVoice restarts with the new choice when it is idle."] = "Activé : MIOpen d’AMD exécute les convolutions, avec MIOPEN_FIND_MODE=2 et MIOPEN_FIND_ENFORCE=1. Désactivé : les convolutions de PyTorch. Laquelle est la plus rapide dépend de ta carte et de ton pilote : si les voix sont lentes ou s’interrompent, essaie l’autre. Cartes AMD uniquement. OmniVoice redémarre avec le nouveau choix quand il est inactif.",
    ["Own Python"] = "Python personnel",
    ["Ready"] = "Prêt",
    ["Ready. OmniVoice runs on {card} with AMD’s ROCm."] = "Prêt. OmniVoice tourne sur {card} avec le ROCm d’AMD.",
    ["Reinstall"] = "Réinstaller",
    ["Remove AMD setup"] = "Retirer la configuration AMD",
    ["Removing the AMD setup…"] = "Retrait de la configuration AMD…",
    ["Run OmniVoice on your AMD Radeon card with AMD’s ROCm: one download, set up from here."] = "Fais tourner OmniVoice sur ta carte AMD Radeon avec le ROCm d’AMD : un seul téléchargement, configuré d’ici.",
    ["Set up OmniVoice for AMD"] = "Configurer OmniVoice pour AMD",
    ["Starting the AMD setup…"] = "Démarrage de la configuration AMD…",
    ["Testing it on your card…"] = "Test sur ta carte…",
    ["The AMD setup was removed."] = "La configuration AMD a été retirée.",
    ["The OmniVoice pack is not installed. Install it first."] = "Le pack OmniVoice n’est pas installé. Installe-le d’abord.",
    ["The conversation service is not running. Restart the game."] = "Le service de conversation ne tourne pas. Redémarre le jeu.",
    ["The download did not finish. Check your connection and try again."] = "Le téléchargement ne s’est pas terminé. Vérifie ta connexion et réessaie.",
    ["The download is not ready yet in this version of the mod."] = "Le téléchargement n’est pas encore disponible dans cette version du mod.",
    ["The downloaded files did not check out. Try again."] = "Les fichiers téléchargés n’ont pas passé la vérification. Réessaie.",
    ["The files could not be unpacked. Try again."] = "Les fichiers n’ont pas pu être décompressés. Réessaie.",
    ["The setup did not finish. Try again."] = "La configuration ne s’est pas terminée. Réessaie.",
    ["The setup did not pass the test on your card, so OmniVoice cannot use it."] = "La configuration n’a pas réussi le test sur ta carte, donc OmniVoice ne peut pas l’utiliser.",
    ["The setup is installed but did not pass the test on your card. Choose Reinstall."] = "La configuration est installée mais n’a pas réussi le test sur ta carte. Choisis Réinstaller.",
    ["There is not enough free space on drive C:. Free some up and try again."] = "Il n’y a pas assez d’espace libre sur le lecteur C:. Libère-en un peu et réessaie.",
    ["This PC has no AMD Radeon card this setup can use."] = "Ce PC n’a pas de carte AMD Radeon que cette configuration peut utiliser.",
    ["Unpacking…"] = "Décompression…",
    ["Your own Python (omni-python.txt) is used instead. Delete that file to use this setup."] = "Ton propre Python (omni-python.txt) est utilisé à la place. Supprime ce fichier pour utiliser cette configuration.",
    ["your AMD card"] = "ta carte AMD",
    ["{voice} · AMD: set up first"] = "{voice} · AMD : configure-le d’abord",
    ["The AMD setup (Settings > Voices > OmniVoice for AMD) runs OmniVoice with ROCm on {card}. Experimental."] = "La configuration AMD (Paramètres > Voix > OmniVoice pour AMD) fait tourner OmniVoice avec ROCm sur {card}. Expérimental.",
    ["The AMD setup was not used: {reason}. Choose Reinstall in Settings > Voices > OmniVoice for AMD. Until then Pocket speaks."] = "La configuration AMD n’a pas été utilisée : {reason}. Choisis Réinstaller dans Paramètres > Voix > OmniVoice pour AMD. En attendant, Pocket parle.",
    ["Borrow eddies from your characters, lend them eddies and pay each other back, by talking. Each character has money of their own, as their story has it, and decides by how they feel about you. Now and then they ask you for a loan.\n\nEddies change hands as soon as a character agrees, and only with your own characters (party, invited visitors, housemates). The game’s own characters only talk about it. Off by default."] = "En discutant, emprunte des eddies à tes personnages, prête-leur et rembourse-les. Chacun a son argent et décide selon ce qu’il pense de toi. Parfois, ils te demandent un prêt.\n\nLes eddies changent de mains dès qu’un personnage accepte, et seulement avec tes propres personnages (groupe, visiteurs, colocataires). Les personnages du jeu en parlent seulement. Désactivé par défaut.",
    ["Eddies with characters"] = "Eddies avec les personnages",
    ["The eddies could not be moved."] = "Le transfert d’eddies n’a pas pu avoir lieu.",
    ["You do not have enough eddies for that."] = "Tu n’as pas assez d’eddies pour ça.",
    ["{name} is no longer with you, so no eddies moved."] = "{name} n’est plus avec toi, donc aucun transfert d’eddies n’a eu lieu.",
    ["Add to favorites"] = "Ajouter aux favoris",
    ["One download of about {size} GB."] = "Un seul téléchargement d’environ {size} GB.",
    ["One download."] = "Un seul téléchargement.",
    ["Use the Search box, top right"] = "Zone de recherche, en haut",
    ["How to search"] = "Comment chercher",
    ["search: {query} · {count} found"] = "recherche : {query} · {count} trouvés",
    ["Empties the Search box and shows the whole list again."] = "Vide la zone de recherche et réaffiche toute la liste.",
    ["Click the Search box at the top right of this panel (it is dim until you click it) and type a name. The list shows every match on every page and letter. Case and accents do not matter, and every word you type has to match the start of a word in the name."] = "Cliquez sur la zone de recherche en haut à droite de ce panneau (elle reste estompée tant que vous ne cliquez pas dessus) et saisissez un nom. La liste montre toutes les correspondances sur toutes les pages et toutes les lettres. La casse et les accents n’ont pas d’importance, et chaque mot saisi doit correspondre au début d’un mot du nom.",
    ["Click the Search box at the top right of this panel and type a name."] = "Cliquez sur la zone de recherche en haut à droite de ce panneau et saisissez un nom.",
    ["Remove {name} from favorites"] = "Retirer {name} des favoris",
    ["Remove {name}"] = "Retirer {name}",
    ["Set up OmniVoice on your AMD Radeon card with one download, and choose how it runs."] = "Configure OmniVoice sur ta carte AMD Radeon avec un seul téléchargement, puis choisis son mode de fonctionnement.",
    ["That entry cannot be a favorite."] = "Cette entrée ne peut pas être un favori.",
    ["You have too many favorites. Remove one first."] = "Tu as trop de favoris. Retires-en d’abord un.",
    ["Your AMD Radeon card ({card}) can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself."] = "Ta carte AMD Radeon ({card}) peut faire tourner OmniVoice. Configure-le dans Paramètres > Voix > OmniVoice pour AMD : un téléchargement, puis il démarre tout seul.",
    ["Your favorites could not be saved, so they last only until the game closes."] = "Tes favoris n’ont pas pu être enregistrés : ils ne tiendront donc que jusqu’à la fermeture du jeu.",
    ["{count} matching characters"] = "{count} personnages correspondants",
    ["{name} is no longer a favorite."] = "{name} n’est plus un favori.",
    ["A saved party holds {count} characters, so the rest were left out."] = "Un groupe enregistré contient {count} personnages, le reste a donc été omis.",
    ["Already with you: {names}."] = "Déjà avec vous : {names}.",
    ["Another saved party already has that name."] = "Un autre groupe enregistré porte déjà ce nom.",
    ["Could not invite: {names}."] = "Impossible d'inviter : {names}.",
    ["Deletes this saved party. The characters in your party now are not touched."] = "Supprime ce groupe enregistré. Les personnages de votre groupe actuel ne sont pas touchés.",
    ["Invites the characters of this party to your side: {names}.\n\nIt adds to your party and dismisses nobody. A character who is already with you is not invited twice. Anyone who cannot come is named, with the reason."] = "Invite les personnages de ce groupe à vous rejoindre : {names}.\n\nIls sont ajoutés à votre groupe et personne n'est renvoyé. Un personnage déjà avec vous n'est pas invité deux fois. Ceux qui ne peuvent pas venir sont nommés, avec la raison.",
    ["Parties"] = "Groupes",
    ["Party"] = "Groupe",
    ["Press Delete again to delete {name}."] = "Appuyez à nouveau sur Supprimer pour supprimer {name}.",
    ["Press again"] = "Appuyez à nouveau",
    ["Press again to delete this saved party. Anything else cancels."] = "Appuyez à nouveau pour supprimer ce groupe enregistré. Toute autre action annule.",
    ["Rename"] = "Renommer",
    ["Rename party"] = "Renommer le groupe",
    ["Renamed to {name}."] = "Renommé en {name}.",
    ["Replaces the characters of this saved party with the ones in your party now."] = "Remplace les personnages de ce groupe enregistré par ceux de votre groupe actuel.",
    ["Save current party"] = "Enregistrer le groupe actuel",
    ["Saved as {name}. Press Spawn party under it to invite them again."] = "Enregistré sous {name}. Appuyez sur Inviter le groupe en dessous pour les inviter à nouveau.",
    ["Saved party: {name}"] = "Groupe enregistré : {name}",
    ["Saves the characters in your party now, copies and your own characters included, as a party you can invite again with one press. It is named Party 1, Party 2 and so on, and appears below.\n\nYou keep up to {count} saved parties."] = "Enregistre les personnages actuellement dans votre groupe, copies et vos propres personnages inclus, comme un groupe que vous pourrez inviter à nouveau d'une seule pression. Il se nomme Groupe 1, Groupe 2 et ainsi de suite, et apparaît ci-dessous.\n\nVous pouvez conserver jusqu'à {count} groupes enregistrés.",
    ["Spawn"] = "Inviter",
    ["Spawn party"] = "Inviter le groupe",
    ["That party no longer exists."] = "Ce groupe n'existe plus.",
    ["The characters of this party: {names}."] = "Les personnages de ce groupe : {names}.",
    ["The party could not be saved."] = "Le groupe n'a pas pu être enregistré.",
    ["This menu has no text box, so the party keeps its name. Mod Configuration Menu has one: type the name in its Search box."] = "Ce menu n'a pas de champ de texte, le groupe conserve donc son nom. Mod Configuration Menu en a un : saisissez le nom dans son champ de recherche.",
    ["Type the new name in the Search box at the top (Mod Configuration Menu), then press Rename. Native Settings UI has no text box, so a party keeps its name there."] = "Saisissez le nouveau nom dans le champ de recherche en haut (Mod Configuration Menu), puis appuyez sur Renommer. Native Settings UI n'a pas de champ de texte, un groupe y conserve donc son nom.",
    ["Type the new name in the Search box first, then press Rename."] = "Saisissez d'abord le nouveau nom dans le champ de recherche, puis appuyez sur Renommer.",
    ["Update"] = "Mettre à jour",
    ["Update with current party"] = "Mettre à jour avec le groupe actuel",
    ["You can keep {count} saved parties. Delete one first."] = "Vous pouvez conserver {count} groupes enregistrés. Supprimez-en un d'abord.",
    ["Your party is empty. Invite someone first."] = "Votre groupe est vide. Invitez d'abord quelqu'un.",
    ["Your saved parties could not be written to disk, so they last only until the game closes."] = "Vos groupes enregistrés n'ont pas pu être écrits sur le disque : ils ne seront conservés que jusqu'à la fermeture du jeu.",
    ["that character model is unavailable"] = "le modèle de personnage est indisponible",
    ["the invitation was refused"] = "l'invitation a été refusée",
    ["{name} ({count})"] = "{name} ({count})",
    ["{name} ({reason})"] = "{name} ({reason})",
    ["{name} deleted."] = "{name} supprimé.",
    ["{name} has nobody to invite."] = "{name} n'a personne à inviter.",
    ["{name} now has the characters of your party."] = "{name} a maintenant les personnages de votre groupe.",
    ["{party}: inviting {names}."] = "{party} : invite {names}.",
    ["Adds {name} to your favorites. They are listed at the top of page 1, and first in the phone’s Chat tab. Updates never touch them."] = "Ajoute {name} aux favoris. Ils sont listés en haut de la page 1, et en premier dans l’onglet Chat du téléphone. Les mises à jour ne les touchent jamais.",
    ["Favorites"] = "Favoris",
    ["Only the first {count} favorites are listed here. The others are in the list below."] = "Seuls les {count} premiers favoris sont listés ici. Les autres sont dans la liste ci-dessous.",
    ["Page {page} of {pages}: {kind} {first} to {last}."] = "Page {page} sur {pages} : {kind} {first} à {last}.",
    ["Press to go to page {page} of {pages}: {kind} {first} to {last}."] = "Appuyer pour aller à la page {page} sur {pages} : {kind} {first} à {last}.",
    ["Takes {name} out of your favorites. Her place in the list below stays."] = "Retire {name} des favoris. Sa place dans la liste ci-dessous reste.",
    ["This is the first page."] = "C’est la première page.",
    ["This is the last page."] = "C’est la dernière page.",
    ["characters"] = "personnages",
    ["entries"] = "entrées",
    ["models"] = "modèles",
    ["{count} more favorites"] = "{count} favoris de plus",
    ["{name} is now a favorite. Favorites are at the top of page 1."] = "{name} est maintenant un favori. Les favoris sont en haut de la page 1.",
    ["Favorite"] = "Favori",
    ["That look is not one of this character’s."] = "Cet aspect n’appartient pas à ce personnage.",
    ["That choice is not available."] = "Ce choix n’est pas disponible.",
    ["The editor keeps choices for {max} characters. Reset one first."] = "L’éditeur conserve les choix de {max} personnages. Réinitialisez-en un d’abord.",
    ["Usual look"] = "Aspect habituel",
    ["Home clothes: tank top, boxer shorts, flip-flops"] = "Vêtements d’intérieur : débardeur, caleçon, tongs",
    ["No jacket"] = "Sans veste",
    ["No jacket and harness"] = "Sans veste, avec harnais",
    ["Home clothes: shirt and trousers"] = "Vêtements d’intérieur : chemise et pantalon",
    ["Home clothes: tank top and trousers"] = "Vêtements d’intérieur : débardeur et pantalon",
    ["Hooded jacket"] = "Veste à capuche",
    ["Home clothes: t-shirt and trousers"] = "Vêtements d’intérieur : t-shirt et pantalon",
    ["Collar down"] = "Col rabattu",
    ["Valentino look"] = "Aspect Valentino",
    ["Suit"] = "Costume",
    ["Club night, no jacket"] = "Soirée en club, sans veste",
    ["Solo look"] = "Aspect Solo",
    ["Date night"] = "Soirée en amoureux",
    ["T-shirt"] = "T-shirt",
    ["Vest"] = "Gilet",
    ["Paradise look"] = "Aspect Paradise",
    ["Bartender"] = "Barman",
    ["Dress without the fur coat"] = "Robe sans manteau de fourrure",
    ["Trench coat"] = "Trench-coat",
    ["Without the coat"] = "Sans le manteau",
    ["CEO look with coat"] = "Aspect CEO avec manteau",
    ["CEO look"] = "Aspect CEO",
    ["Pyjamas"] = "Pyjama",
    ["Valentino look, collar open"] = "Aspect Valentino, col ouvert",
    ["Vest and rucksack"] = "Gilet et sac à dos",
    ["Arasaka work clothes, no jacket"] = "Tenue de travail Arasaka, sans veste",
    ["Red parade dress"] = "Robe rouge de défilé",
    ["Red parade dress with bracelets"] = "Robe rouge de défilé avec bracelets",
    ["Party dress"] = "Robe de soirée",
    ["Tank top"] = "Débardeur",
    ["Street clothes"] = "Tenue de ville",
    ["Merc look"] = "Aspect mercenaire",
    ["Go back to the usual look and moves for {name}? Your choices on this part are removed."] = "Revenir à l’aspect et aux mouvements habituels de {name} ? Vos choix dans cette partie seront supprimés.",
    ["Back to the usual look and moves."] = "Retour à l’aspect et aux mouvements habituels.",
    ["Choices for how this character looks and moves. They work with every conversation option, Convai included, except the reply length."] = "Choix de l’apparence et des mouvements de ce personnage. Ils fonctionnent avec toutes les options de conversation, Convai compris, sauf la longueur des réponses.",
    ["Outfit"] = "Tenue",
    ["Automatic follows the “Companions change outfits” setting in the game: day and night looks, now and then a change, and casual clothes at home. A look you pick is worn all the time. Only your own companions and residents are dressed, and they change while nobody is looking. Characters the game places are never changed."] = "Automatique suit le réglage « Compagnons changent de tenue » du jeu : aspects de jour et de nuit, un changement de temps en temps et vêtements décontractés à la maison. Un aspect choisi est porté en permanence. Seuls vos propres compagnons et résidents sont habillés, et ils changent quand personne ne regarde. Les personnages placés par le jeu ne sont jamais modifiés.",
    ["This character has only one look in the game files, so there is no outfit to choose."] = "Ce personnage n’a qu’un seul aspect dans les fichiers du jeu, il n’y a donc pas de tenue à choisir.",
    ["Talking gestures"] = "Gestes pendant la parole",
    ["How the hands move while they speak a longer reply."] = "Mouvements des mains lorsqu’ils prononcent une réponse plus longue.",
    ["Normal"] = "Normal",
    ["Calm: smaller gestures, not as often"] = "Calme : gestes plus petits, moins souvent",
    ["Lively: bigger gestures, more often"] = "Vif : gestes plus amples, plus souvent",
    ["None: the hands stay at rest"] = "Aucun : les mains restent au repos",
    ["Nod while you talk to them"] = "Hocher la tête quand vous leur parlez",
    ["A small nod now and then while you speak."] = "Un petit hochement de tête de temps en temps pendant que vous parlez.",
    ["Idle moves"] = "Mouvements au repos",
    ["What they do now and then while they stand beside you."] = "Ce qu’ils font de temps en temps en se tenant à côté de vous.",
    ["Plain stances only, no props like a cup or a cigarette"] = "Postures simples uniquement, sans accessoires comme une tasse ou une cigarette",
    ["None: they keep the stance they have"] = "Aucun : ils gardent leur posture",
    ["Sit down and take a place"] = "S’asseoir et prendre place",
    ["Takes a seat beside you when you sit, and a seat or a spot in your flat at home. Switched off, they stay on their feet beside you."] = "Prend place à côté de vous quand vous vous asseyez, et occupe un siège ou un endroit dans votre appartement. Désactivé, ils restent debout à vos côtés.",
    ["Comment on fights and loot"] = "Commenter les combats et le butin",
    ["Switched off, they say nothing about fights or about what you pick up."] = "Désactivé, ils ne disent rien sur les combats ni sur ce que vous ramassez.",
    ["Reply length"] = "Longueur des réponses",
    ["Shorter: up to about {words} words"] = "Plus courte : jusqu’à environ {words} mots",
    ["Very short: up to about {words} words"] = "Très courte : jusqu’à environ {words} mots",
    ["A saved choice counts within a few seconds. Clothes change when nobody is looking."] = "Un choix enregistré prend effet en quelques secondes. Les vêtements changent quand personne ne regarde.",
    ["Look and moves"] = "Aspect et mouvements",
    ["Shift"] = "Maj",
    ["Ctrl"] = "Ctrl",
    ["Alt"] = "Alt",
    ["Hold Shift, Ctrl or Alt while you press a key to set a combination such as Shift+F5. A combination runs only with exactly those keys held, and a plain key does not run while one is held. In the game Shift sprints, Ctrl dodges and Alt opens the weapon wheel, so V does that too."] = "Maintenez Maj, Ctrl ou Alt en appuyant sur une touche pour définir une combinaison comme Maj+F5. Une combinaison ne se déclenche qu’avec exactement ces touches maintenues, et une touche simple ne se déclenche pas tant que l’une d’elles est maintenue. Dans le jeu, Maj fait sprinter, Ctrl esquiver et Alt ouvre la roue des armes, donc V le fait aussi.",
    ["Disk space"] = "Espace disque",
    ["Your {drive} drive is almost full ({free} GB free). Free space so the mod can save logs and memories."] = "Ton lecteur {drive} est presque plein ({free} Go libres). Fais de la place pour les logs et souvenirs du mod.",
    ["An input marked (!) looks like a loopback or virtual input, such as Stereo Mix, CABLE Output or a mixer’s Out. It can carry other apps’ sound, for example the far side of a call, so the mod never picks one by itself."] = "Une entrée marquée (!) ressemble à une entrée de bouclage ou virtuelle, comme Stereo Mix, CABLE Output ou la sortie d'un mixeur. Elle peut transmettre le son d'autres applications, par exemple l'autre côté d'un appel, donc le mod n'en choisit jamais une seule.",
    ["The input you chose looks like it carries PC sound, not only your voice. If characters hear your calls, choose your real microphone."] = "L'entrée que vous avez choisie semble transmettre le son du PC, et pas seulement votre voix. Si les personnages entendent vos appels, choisissez votre vrai microphone.",
    ["{name} looks like it carries PC sound, such as a call, not only your voice. Choose your real microphone in Settings > Voices > Microphone."] = "{name} semble transmettre le son du PC, par exemple un appel, et pas seulement votre voix. Choisissez votre vrai microphone dans Paramètres > Voix > Microphone.",
    ["No API key is saved yet. Copy your key from your provider, press Paste API key, then test again."] = "Aucune clé d’API n’est encore enregistrée. Copiez votre clé auprès de votre fournisseur, appuyez sur Coller la clé d’API, puis testez à nouveau.",
    ["Add"] = "Ajouter",
    ["Deletes this free setup: the endpoint URL, the model ID and the API key saved with it."] = "Supprime cette configuration gratuite : l’URL d’endpoint, l’identifiant du modèle et la clé enregistrée avec elle.",
    ["Allow Local AI to use RAM"] = "Autoriser Local AI à utiliser la RAM",
    ["Off: when the Local AI model you chose does not fit the free graphics memory beside the game, a smaller model that fits is loaded instead, with one notice.\n\nOn: your chosen model is kept and part of it runs from system memory (RAM) on the processor. Replies are slower, and you are told once. It needs enough free RAM, and the game may have less processor time."] = "Désactivé : si le modèle Local AI choisi ne tient pas dans la mémoire vidéo libre à côté du jeu, un modèle plus petit est chargé à la place, avec une notification.\n\nActivé : le modèle choisi est conservé et une partie tourne depuis la mémoire système (RAM) sur le processeur. Les réponses sont plus lentes, vous en êtes informé une fois. Il faut assez de RAM libre, et le jeu peut avoir moins de temps processeur.",
    ["Using {model}"] = "Utilise {model}",
    ["{model} is in use because the model you chose did not fit beside the game. Your choice is unchanged."] = "{model} est utilisé, car le modèle choisi ne tenait pas à côté du jeu. Votre choix ne change pas.",
    ["Local AI is keeping {model} as you allowed, with part of it in system memory. Replies will be slower."] = "Local AI garde {model} comme vous l’avez autorisé, avec une partie dans la mémoire système. Les réponses seront plus lentes.",
    ["Choosing Convai or Google Gemini turns it off. Voxtral is not used with it: a voice on Voxtral moves to Pocket and comes back when it is turned off."] = "Choisir Convai ou Google Gemini désactive ceci. Voxtral n’est pas utilisé avec ceci : une voix Voxtral passe sur Pocket et revient quand ceci est désactivé.",
    ["Convai could not sign in. Try again in a moment, or choose Google Gemini or Local AI in Settings > Conversation provider."] = "Connexion à Convai impossible. Réessayez dans un instant, ou choisissez Google Gemini ou Local AI dans Paramètres > Fournisseur de conversation.",
    ["Convai is answering right now, so these changes have no effect yet. Choose Google Gemini, Local AI or Custom as the conversation provider in the settings."] = "Convai répond en ce moment, donc ces modifications n’ont pas encore d’effet. Choisissez Google Gemini, Local AI ou Personnalisé comme fournisseur de conversation dans les paramètres.",
    ["Convai: Google Gemini has no key yet"] = "Convai : Google Gemini n'a pas encore de clé",
    ["Copy your Mistral API key first, then press Add. It fills in the endpoint URL and the model ID for Mistral (Ministral 8B) and saves your key from the clipboard. The same key powers the Voxtral cloud voice.\n\nNew Mistral accounts may not get a free API key any more."] = "Copiez d’abord votre clé d’API Mistral, puis appuyez sur Add. Elle remplit l’URL d’endpoint et l’identifiant du modèle pour Mistral (Ministral 8B), et enregistre votre clé depuis le presse-papiers. La même clé alimente la voix cloud Voxtral.\n\nLes nouveaux comptes Mistral ne recevront peut-être plus de clé d’API gratuite.",
    ["Copy your key from Google AI Studio first (aistudio.google.com/apikey, a Google account is enough, no card). It is read from the clipboard once and saved on this computer.\n\nThe free plan has a daily limit of about 500 replies, is not offered in every country, and Google may use free-plan chats to improve its products."] = "Copiez d’abord votre clé depuis Google AI Studio (aistudio.google.com/apikey, un compte Google suffit, sans carte). Elle est lue une fois dans le presse-papiers et enregistrée sur cet ordinateur.\n\nL’offre gratuite a une limite quotidienne d’environ 500 réponses, n’est pas proposée dans tous les pays, et Google peut utiliser les conversations de l’offre gratuite pour améliorer ses produits.",
    ["Edit a character’s bio, speaking style, speaking rules and memories, and the prompting for each AI option, or make a character of your own, in your browser.\n\nWorks with Google Gemini, Local AI and Custom, not Convai. Changes apply from the next reply."] = "Modifiez, dans votre navigateur, la biographie, le style de parole, les règles de parole et les souvenirs d’un personnage, ainsi que le prompt de chaque option d’IA, ou créez le vôtre.\n\nFonctionne avec Google Gemini, Local AI et Personnalisé, pas avec Convai. Les modifications s’appliquent dès la prochaine réponse.",
    ["Edit characters’ bios, rules and memories, and the prompting for each AI option, in your browser.\n\nWorks with Google Gemini, Local AI and Custom, not Convai. Changes apply from the next reply."] = "Modifiez, dans votre navigateur, les biographies, les règles et les souvenirs des personnages, ainsi que le prompt de chaque option d’IA.\n\nFonctionne avec Google Gemini, Local AI et Personnalisé, pas avec Convai. Les modifications s’appliquent dès la prochaine réponse.",
    ["From Convai or Google Gemini, turning it on selects Local AI, or Custom when Local AI is not installed. With Local AI it also selects the largest uncensored model that fits. Turning it off restores your choices."] = "Depuis Convai ou Google Gemini, l’activer sélectionne Local AI, ou Personnalisé si Local AI n’est pas installée. Avec Local AI, il sélectionne aussi le plus grand modèle non censuré qui tient. La désactiver restaure vos choix.",
    ["Google Gemini (free plan)"] = "Google Gemini (gratuit)",
    ["Google Gemini API key"] = "Clé d’API Google Gemini",
    ["Google Gemini has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "Google Gemini n'a pas encore de clé, Convai est donc utilisé. Ajoutez votre clé dans Paramètres > Fournisseur de conversation.",
    ["Google Gemini replies are spoken by a local voice instead of the Convai cloud voice."] = "Les réponses de Google Gemini sont prononcées par une voix locale au lieu de la voix cloud de Convai.",
    ["Google Gemini: key not accepted"] = "Google Gemini : clé non acceptée",
    ["The service is not available in your region."] = "Le service n’est pas disponible dans votre région.",
    ["Google accepted the key."] = "Google a accepté la clé.",
    ["Google did not accept this key. Check it in Google AI Studio, then Remove it and Add the right one."] = "Google n’a pas accepté cette clé. Vérifiez-la dans Google AI Studio, puis cliquez sur Retirer et ajoutez la bonne avec Ajouter.",
    ["Google accepted the key, but the free allowance is used up for now."] = "Google a accepté la clé, mais le quota gratuit est épuisé pour le moment.",
    ["The key is saved, but Google Gemini is not available in your region."] = "La clé est enregistrée, mais Google Gemini n’est pas disponible dans votre région.",
    ["The key is saved, but Google could not be reached to check it."] = "La clé est enregistrée, mais Google n’a pas pu être contacté pour la vérifier.",
    ["Google Gemini: rate limited for a minute"] = "Google Gemini : limité pendant une minute",
    ["Google Gemini: free allowance used up for today"] = "Google Gemini : quota gratuit épuisé pour aujourd’hui",
    ["Google Gemini: not available in your region"] = "Google Gemini : non disponible dans votre région",
    ["Google did not accept your Gemini key. Check it in Google AI Studio and add it again."] = "Google n’a pas accepté votre clé Gemini. Vérifiez-la dans Google AI Studio et réajoutez-la.",
    ["Your free Gemini allowance for today is used up. It resets at {time}. Use Convai or Local AI."] = "Quota Gemini gratuit épuisé pour aujourd’hui. Réinitialisation à {time}. Utilisez Convai ou Local AI.",
    ["Your free Gemini allowance for today is used up. It resets tomorrow. Use Convai or Local AI."] = "Quota Gemini gratuit épuisé pour aujourd’hui. Réinitialisation demain. Utilisez Convai ou Local AI.",
    ["Google Gemini is rate limiting you. Wait a minute, then try again."] = "Google Gemini vous limite. Attendez une minute, puis réessayez.",
    ["Google Gemini is not available in your region. Use Convai or Local AI."] = "Google Gemini n’est pas disponible dans votre région. Utilisez Convai ou Local AI.",
    ["Google Gemini is busy or had an error. Wait a minute, then try again."] = "Google Gemini est occupé ou a eu une erreur. Attendez une minute, puis réessayez.",
    ["Google Gemini could not be reached. Check your internet connection, then try again."] = "Google Gemini est injoignable. Vérifiez votre connexion, puis réessayez.",
    ["The Gemini model is not available right now. Try again later or use Local AI."] = "Le modèle Gemini n’est pas disponible. Réessayez plus tard ou utilisez Local AI.",
    ["Google Gemini: model unavailable"] = "Google Gemini : modèle indisponible",
    ["Mistral (your key)"] = "Mistral (votre clé)",
    ["Requires a Mistral key (add it with the Mistral preset on the Custom endpoint page)"] = "Nécessite une clé Mistral (ajoutez-la avec le préréglage Mistral sur la page Custom endpoint)",
    ["The conversation limit has been reached. Try again later, or choose Local AI or Google Gemini in Settings > Conversation provider."] = "La limite de conversations a été atteinte. Réessayez plus tard, ou choisissez Local AI ou Google Gemini dans Paramètres > Fournisseur de conversation.",
    ["The longest reply, in words. Works with Google Gemini, Local AI and Custom, not Convai."] = "La réponse la plus longue, en mots. Fonctionne avec Google Gemini, Local AI et Custom, pas avec Convai.",
    ["They join as a copy of the model they were made from. They talk with Google Gemini, Local AI or Custom; with Convai they talk as an ordinary person."] = "Il rejoint le groupe comme une copie du modèle dont il est issu. Il parle avec Google Gemini, Local AI ou Personnalisé ; avec Convai, il parle comme une personne ordinaire.",
    ["Today’s Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "Tours Convai épuisés.\nRéinitialisation à {time}. Essayez Local AI (illimitée) ou Google Gemini (votre propre clé).",
    ["Today’s Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "Tours Convai épuisés.\nEssayez Local AI (illimitée) ou Google Gemini (votre propre clé).",
    ["Today’s {limit} Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "{limit} tours Convai épuisés.\nRéinitialisation à {time}. Essayez Local AI (illimitée) ou Google Gemini (votre propre clé).",
    ["Today’s {limit} Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "{limit} tours Convai épuisés.\nEssayez Local AI (illimitée) ou Google Gemini (votre propre clé).",
    ["Turns the content pack {name} on or off. A pack changes how the characters talk. Its prompt changes work with Google Gemini, Local AI and Custom. On Convai its world rules and its own Convai characters apply. A switch counts from the next reply, new names after a restart."] = "Active ou désactive le paquet de contenu {name}. Un paquet change la façon dont les personnages parlent. Ses modifications de prompt fonctionnent avec Google Gemini, Local AI et Personnalisé. Sur Convai, ses règles du monde et ses propres personnages Convai s’appliquent. Un changement compte à partir de la prochaine réponse, les nouveaux noms après un redémarrage.",
    ["What the game tells each character about this moment. A character mentions it only when it fits the talk.\n\nAn off kind is left out of every conversation provider (Convai, Google Gemini, Local AI and Custom)."] = "Ce que le jeu indique à chaque personnage sur ce moment. Un personnage n’en parle que lorsque cela s’intègre à la conversation.\n\nUne information désactivée est exclue de tous les fournisseurs de conversation (Convai, Google Gemini, Local AI et Personnalisé).",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "Qui rédige les réponses de vos compagnons. Un changement attend qu’aucune conversation ne soit en cours.\n\nL’offre gratuite de Convai ne demande aucune configuration et donne de meilleures réponses. L’option Clé d’API Convai utilise votre propre clé. Google Gemini utilise votre propre clé gratuite, et sa mémoire reste sur cet ordinateur.\n\nAvec Google Gemini, Local AI ou Personnalisé, la voix cloud de Convai est remplacée par une voix locale. La parole est reconnue sur cet ordinateur, donc la touche vocale fonctionne.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "Qui rédige les réponses de vos compagnons. Un changement attend qu’aucune conversation ne soit en cours.\n\nL’offre gratuite de Convai ne demande aucune configuration et donne de meilleures réponses. L’option Clé d’API Convai utilise votre propre clé. Google Gemini utilise votre propre clé gratuite, et sa mémoire reste sur cet ordinateur.\n\nAvec Google Gemini, Local AI ou Personnalisé, la voix cloud de Convai est remplacée par une voix locale. La reconnaissance vocale pour la touche vocale n’est pas encore disponible avec eux, donc tapez vos messages.",
    ["You have used today’s {limit} turns, which come back at {time}. To keep talking now, choose Local AI (unlimited) or Google Gemini (with your own key)."] = "Vous avez utilisé vos {limit} tours du jour. Ils reviennent à {time}. Pour continuer dès maintenant, choisissez Local AI (aucune limite) ou Google Gemini (avec votre propre clé).",
    ["You have used today’s {limit} turns, which come back tomorrow. To keep talking now, choose Local AI (unlimited) or Google Gemini (with your own key)."] = "Vous avez utilisé vos {limit} tours du jour. Ils reviennent demain. Pour continuer dès maintenant, choisissez Local AI (aucune limite) ou Google Gemini (avec votre propre clé).",
    ["Your changes work with Google Gemini, Local AI and Custom. They do not apply to Convai."] = "Vos modifications fonctionnent avec Google Gemini, Local AI et Personnalisé. Elles ne s’appliquent pas à Convai.",
    ["Your own characters talk only with Google Gemini, Local AI or Custom. With Convai they speak as an ordinary person."] = "Vos propres personnages ne parlent qu’avec Google Gemini, Local AI ou Personnalisé. Avec Convai, ils parlent comme une personne ordinaire.",
    ["{name} is one of your own characters. They need Google Gemini, Local AI or Custom, so with Convai they talk as an ordinary person."] = "{name} est l’un de vos propres personnages. Il a besoin de Google Gemini, de Local AI ou de Personnalisé, donc avec Convai il parle comme une personne ordinaire.",
    ["{name} is one of your own characters. They need Google Gemini, Local AI or Custom: choose one under Conversation provider in the settings."] = "{name} est l’un de vos propres personnages. Ce personnage a besoin de Google Gemini, Local AI ou Custom : choisissez-en un dans les paramètres, sous « Fournisseur de conversation ».",
    ["This character needs Google Gemini, Local AI or Custom to answer."] = "Ce personnage a besoin de Google Gemini, Local AI ou Personnalisé pour répondre.",
    ["You’ve reached today’s Convai free tier limit. It resets at {time}. To keep talking now, choose another provider in Settings > Conversation provider. Local AI is unlimited and runs on your PC. Google Gemini works with your own key."] = "Vous avez atteint la limite quotidienne de Convai (offre gratuite). Elle se réinitialise à {time}. Pour continuer dès maintenant, choisissez un autre fournisseur dans Paramètres > Fournisseur de conversation. Local AI est illimitée et fonctionne sur votre PC. Google Gemini fonctionne avec votre propre clé.",
    ["You’ve reached today’s Convai free tier limit. It resets tomorrow. To keep talking now, choose another provider in Settings > Conversation provider. Local AI is unlimited and runs on your PC. Google Gemini works with your own key."] = "Vous avez atteint la limite quotidienne de Convai (offre gratuite). Elle se réinitialise demain. Pour continuer dès maintenant, choisissez un autre fournisseur dans Paramètres > Fournisseur de conversation. Local AI est illimitée et fonctionne sur votre PC. Google Gemini fonctionne avec votre propre clé.",
    ["Character bonds"] = "Liens avec les personnages",
    ["Every named character has a bond with you, level 1 to 10. Quests finished together, a romance, eddies paid back and talking raise it; threats and insults lower it. Closer characters trust you more.\n\nA notice shows each level change. Forget clears the talk part. Off by default."] = "Chaque personnage a un lien avec toi, du niveau 1 au 10. Il monte avec les quêtes finies ensemble, une romance, les eddies rendus et les discussions ; les menaces et insultes le font baisser. Les plus proches te font davantage confiance.\n\nUne notification signale chaque changement. Effacer supprime la partie discussion. Désactivé par défaut.",
    ["Bond with {name}: level {level}, {title}"] = "Lien avec {name} : niveau {level}, {title}",
    ["Bond with {name} fell: level {level}, {title}"] = "Lien avec {name} en baisse : niveau {level}, {title}",
    ["Acquaintance"] = "Connaissance",
    ["Familiar face"] = "Visage connu",
    ["Friendly"] = "Amical",
    ["Friend"] = "Ami",
    ["Good friend"] = "Bon ami",
    ["Close friend"] = "Ami proche",
    ["Trusted"] = "De confiance",
    ["Confidant"] = "Confident",
    ["Family"] = "Famille",
    ["Ride or die"] = "Ami à la mort",
    ["Story packs"] = "Histoires de personnages",
    ["When you are close and a character’s own quests are done, they can start a short story of their own. It plays out in talks, texts and calls, and some use Eddies with characters and Immersive invitations.\n\nNeeds Character bonds. Own characters and channels only, never the game’s own scenes or quests. Off by default."] = "Quand tu es proche d’un personnage et que ses propres quêtes sont finies, il peut lancer une courte histoire à lui. Elle se déroule dans les discussions, messages et appels, et certaines utilisent Eddies avec les personnages et Invitations immersives.\n\nNécessite Liens avec les personnages. Seulement tes personnages et canaux, jamais les scènes ou quêtes du jeu. Désactivé par défaut.",
    ["Characters text first"] = "Les personnages écrivent en premier",
    ["Bond: level {level}, {title}"] = "Lien : niveau {level}, {title}",
    ["Story: {title}"] = "Histoire : {title}",
    ["Bonds are not kept while Character bonds is off, so nobody is listed here. Turn it on in Settings, under Companions."] = "Les liens ne sont pas enregistrés tant que Liens avec les personnages est désactivé, donc personne n’est listé ici. Activez-le dans Paramètres, sous Compagnons.",
    ["Character bonds are off"] = "Liens avec les personnages désactivé",
    ["From their story: {story}, from talking: {talk}"] = "Par son histoire : {story}, par les discussions : {talk}",
    ["Highest level"] = "Niveau maximal",
    ["Hurt: {points}"] = "Froissé : {points}",
    ["Hurt: {points}, gone in about a game day"] = "Froissé : {points}, passera dans environ un jour de jeu",
    ["Hurt: {points}, gone in about {days} game days"] = "Froissé : {points}, passera dans environ {days} jours de jeu",
    ["Last talked: today"] = "Dernière discussion : aujourd’hui",
    ["Last talked: yesterday"] = "Dernière discussion : hier",
    ["Last talked: {days} days ago"] = "Dernière discussion : il y a {days} jours",
    ["Level {level}"] = "Niveau {level}",
    ["No story yet"] = "Pas encore d’histoire",
    ["Nobody yet"] = "Personne pour l’instant",
    ["See the characters you have talked to and how close each one is to you: the bond level, what raised or hurt it, their quests and the stories they are in."] = "Voyez les personnages à qui vous avez parlé et à quel point chacun vous est proche : le niveau du lien, ce qui l’a fait monter ou l’a abîmé, leurs quêtes et les histoires dans lesquelles ils sont.",
    ["Talk to a character and your bond with them shows here."] = "Parlez à un personnage et votre lien avec lui s’affiche ici.",
    ["The characters you have talked to and how close each one is to you. The most recent come first."] = "Les personnages à qui vous avez parlé et à quel point chacun vous est proche. Les plus récents viennent en premier.",
    ["Their quests: {done} of {total} finished"] = "Leurs quêtes : {done} sur {total} terminées",
    ["Warmth: {points}"] = "Chaleur : {points}",
    ["{points} of {needed} points to level {to}"] = "{points} sur {needed} points pour le niveau {to}",
    ["{title} (finished)"] = "{title} (terminée)",
    ["{title}: {label}"] = "{title} : {label}",
    ["Characters you are close to can text or call you first now and then, and Johnny can speak up in your head. It only happens at calm moments, never in a fight, a scene or a call, and only a few times a day.\n\nNeeds Story packs. Own characters and channels only. Off by default."] = "Les personnages dont tu es proche peuvent de temps en temps t’écrire ou t’appeler en premier, et Johnny peut se manifester dans ta tête. Cela n’arrive qu’à des moments calmes, jamais pendant un combat, une scène ou un appel, et seulement quelques fois par jour.\n\nNécessite Histoires de personnages. Seulement tes personnages et canaux. Désactivé par défaut.",
    ["Puts every setting on Settings, Romantic relationships, Dynamic info and Key bindings back to its default. Press the button twice to confirm."] = "Remet chaque paramètre des Paramètres, des Relations romantiques, des Infos en direct et des Raccourcis à sa valeur par défaut. Appuyez deux fois sur le bouton pour confirmer.",
    ["Romantic relationships"] = "Relations romantiques",
    ["Add a key first"] = "Ajoutez d’abord une clé",
    ["Add a key to choose it"] = "Ajoutez une clé pour la choisir",
    ["Asks Inworld whether your saved key is accepted. It costs nothing and no speech is made."] = "Demande à Inworld si votre clé enregistrée est acceptée. Cela ne coûte rien et aucune voix n’est générée.",
    ["Chosen as the Companion voice"] = "Choisie comme voix du compagnon",
    ["Connected"] = "Connecté",
    ["Deletes the saved key. If Inworld is your Companion voice, replies show as text until you add a key again."] = "Supprime la clé enregistrée. Si Inworld est votre voix des compagnons, les réponses s’affichent en texte jusqu’à ce que vous ajoutiez à nouveau une clé.",
    ["Inworld API key"] = "Clé d’API Inworld",
    ["Inworld cloud voice"] = "Voix cloud Inworld",
    ["Inworld did not accept that key."] = "Inworld n'a pas accepté cette clé.",
    ["Inworld is not used with Mature content."] = "Inworld n’est pas utilisé avec le Contenu pour adultes.",
    ["Inworld voice"] = "Voix Inworld",
    ["Inworld · Cloud voice"] = "Inworld · Voix cloud",
    ["Inworld · needs key"] = "Inworld · clé requise",
    ["Inworld · not with Mature"] = "Inworld · pas avec 18+",
    ["Key refused"] = "Clé refusée",
    ["Needs your own Inworld key, from inworld.ai. Inworld’s free plan is a one-time trial of about 70 minutes of speech, then you pay as you go.\n\nCopy your key first, then press Add. It is read from the clipboard once, checked with Inworld and saved on this computer."] = "Il vous faut votre propre clé Inworld, obtenue sur inworld.ai. L’offre gratuite d’Inworld est un essai unique d’environ 70 minutes de voix, puis vous payez à l’usage.\n\nCopiez d’abord votre clé, puis appuyez sur Ajouter. Elle est lue une fois depuis le presse-papiers, vérifiée par Inworld et enregistrée sur cet ordinateur.",
    ["Not reachable"] = "Injoignable",
    ["Not used with Mature content"] = "Non utilisé avec le Contenu pour adultes",
    ["Ready to choose in Companion voices"] = "Prête à être choisie dans Voix des compagnons",
    ["Requires an Inworld key (add it in Settings > Voices > Custom voices)"] = "Nécessite une clé Inworld (ajoutez-la dans Paramètres > Voix > Voix personnalisées)",
    ["Speaks each companion in their own voice, on your own Inworld key. Works in English and the other languages Inworld supports. Choose it under Companion voices, where it is listed last once a key is added."] = "Parle avec la voix propre à chaque compagnon, avec votre propre clé Inworld. Fonctionne en anglais et dans les autres langues prises en charge par Inworld. Choisissez-la dans Voix des compagnons, où elle figure en dernier une fois une clé ajoutée.",
    ["{voice} · needs Inworld key"] = "{voice} · nécessite la clé d'API Inworld",
    ["Choose a character to start editing."] = "Choisissez un personnage pour commencer à le modifier.",
    ["Clear search"] = "Effacer la recherche",
    ["Companion"] = "Compagnon",
    ["Companions"] = "Compagnons",
    ["Custom voice"] = "Voix personnalisée",
    ["Close"] = "Fermer",
    ["In front of you"] = "Devant vous",
    ["You have switched off as many people as the editor keeps ({max}). Switch one back on first."] = "Vous avez désactivé autant de personnes que l'éditeur en garde ({max}). Réactivez-en une d'abord.",
    ["That person cannot be switched off."] = "Cette personne ne peut pas être désactivée.",
    ["Don’t talk to this character"] = "Ne pas parler à ce personnage",
    ["While this is on, they do not answer you and never join a group chat. Untick it to talk to them again."] = "Tant que c'est activé, ils ne vous répondent pas et ne rejoignent jamais un chat de groupe. Décochez-le pour leur parler à nouveau.",
    ["Switched off."] = "Désactivé.",
    ["Switched back on."] = "Réactivé.",
    ["Switch back on"] = "Réactiver",
    ["Don’t talk to this person"] = "Ne pas parler à cette personne",
    ["It also stops everyone the game builds from the same record, so other people of the same kind may stop answering too."] = "Cela arrête aussi tous ceux que le jeu construit à partir du même dossier, donc d'autres personnes de la même sorte pourraient aussi cesser de répondre.",
    ["Switched off"] = "Désactivé",
    ["People and characters you chose not to talk to. Switch one back on to talk to them again."] = "Personnes et personnages auxquels vous avez choisi de ne pas parler. Réactivez-en un pour leur parler à nouveau.",
    ["Recently edited"] = "Modifiés récemment",
    ["Romance"] = "Romance",
    ["Romances"] = "Romances",
    ["Side character"] = "Personnage secondaire",
    ["Side characters"] = "Personnages secondaires",
    ["Minor character"] = "Personnage mineur",
    ["Minor characters"] = "Personnages mineurs",
    ["Story"] = "Histoire",
    ["Story character"] = "Personnage de l’histoire",
    ["Unsaved changes"] = "Modifications non enregistrées",
    ["Together"] = "Ensemble",
    ["You and {name} are together. This grew from talking and is kept in this save. To end it, tell them."] = "Vous et {name} êtes ensemble. Cela s'est construit par les conversations et est sauvegardé dans cet enregistrement. Pour terminer, dites-le.",
    ["A gang you keep killing may rarely send a small squad after you, with a short threat to shout. A long wait follows each one.\n\nNever in a fight, scene, call, vehicle, indoors, safe zone or while wanted."] = "Un gang que vous ne cessez de tuer peut rarement envoyer une petite escouade avec une courte menace. Une longue attente suit chacune.\n\nJamais pendant un combat, une scène, un appel, en véhicule, à l'intérieur, en zone sûre ou pendant une recherche.",
    ["A nearby companion comments as combat starts and ends, and after you collect loot from the world. Storage transfers stay silent.\n\nCooldowns: ten minutes after a fight and between ordinary loot comments, two minutes for new Legendary gear. Pickups during a fight become one comment at its end. Conversations and story scenes come first. Loading a save resets the cooldowns."] = "Un compagnon proche commente au début et à la fin d'un combat, et après un ramassage de butin. Les transferts de stockage restent silencieux.\n\nDélais : dix minutes après un combat et entre les commentaires de butin, deux minutes pour un équipement légendaire neuf. Les ramassages en combat donnent un seul commentaire à la fin. Conversations et scènes passent en premier. Charger une sauvegarde réinitialise les délais.",
    ["AI provider"] = "Fournisseur IA",
    ["Choose how V’s voice is used."] = "Choisissez comment la voix de V est utilisée.",
    ["Companion vision"] = "Vision des compagnons",
    ["Companion voice volume (%)"] = "Volume de la voix des compagnons (%)",
    ["Companions react"] = "Les compagnons réagissent",
    ["Each line also comes with vision: a recent view of your surroundings, taken from the game window just before you talk. Works with every conversation provider. Local AI needs a model with vision. A model without it just gets your words.\n\nOnly the game window, only while someone is near, kept briefly in memory. Off means nothing is captured."] = "Chaque réplique vient avec vision: une image récente de votre environnement, prise de la fenêtre du jeu avant vous parler. Fonctionne avec tous les fournisseurs de conversation. Local AI a besoin d'un modèle avec vision, sinon il ne reçoit que vos mots.\n\nUniquement la fenêtre du jeu, si quelqu'un est proche, brièvement en mémoire. Désactivé, rien n'est capturé.",
    ["Error reports, developer mode and help."] = "Rapports d'erreur, mode développeur et aide.",
    ["How everyone sounds, and how you talk."] = "Comment tout le monde sonne, et comment vous parlez.",
    ["How the world reacts to V."] = "Comment le monde réagit à V.",
    ["Life with your party."] = "Vie avec votre groupe.",
    ["Night City"] = "Night City",
    ["Off: V is silent.\n\nTyped lines: the lines you type are spoken out loud too, in the V voice that matches yours, then the companion answers.\n\nTyped and spoken lines: what you say by microphone (hold to talk or Voice activation) is also spoken by V, and the reply follows V’s line.\n\nV’s line is always waited for, up to about 30 s without audio. The next row picks the voice engine."] = "Désactivé: V est silencieux.\n\nRépliques tapées: ce que vous tapez est aussi dit à voix haute, avec la voix de V qui vous correspond, puis le compagnon répond.\n\nRépliques tapées et parlées: ce que vous dites par microphone (maintenez pour parler ou Activation vocale) est aussi dit par V, et la réponse vient après.\n\nLa réplique de V est toujours attendue (30 s sans son au plus). La ligne suivante choisit le moteur.",
    ["Privacy and help"] = "Confidentialité et aide",
    ["Return to the settings categories."] = "Retour aux catégories de paramètres.",
    ["Return to {page}."] = "Retour à {page}.",
    ["The language of the menus and how subtitles look."] = "La langue des menus et l'apparence des sous-titres.",
    ["The voice V speaks with, whatever the companions use. It counts only while V’s voice is not Off.\n\nPocket: on your processor, about 0.2 s (its own small model if the companions use another voice). Voxtral: cloud, with your Mistral key. OmniVoice: the companions’ GPU voice, a second more wait."] = "La voix avec laquelle parle V, quelle que soit celle des compagnons. Cela compte uniquement tandis que la voix de V n'est pas Désactivée.\n\nPocket: sur votre processeur, environ 0,2 s (avec son propre petit modèle si les compagnons ont une autre voix). Voxtral: cloud, avec votre clé Mistral. OmniVoice: la voix GPU des compagnons, une seconde de plus.",
    ["The yellow border is Windows showing a capture. Turn off Companion vision to stop it."] = "La bordure jaune est Windows qui affiche une capture. Désactivez Vision des compagnons.",
    ["This Local AI model has no vision, so replies use only your words."] = "Ce modèle Local AI n'a pas la vision, les réponses n'utilisent donc que vos mots.",
    ["This model has vision with its vision file, from {folder}/vision on Hugging Face."] = "Ce modèle a la vision avec son fichier de vision, depuis {folder}/vision sur Hugging Face.",
    ["Typed and spoken lines"] = "Répliques tapées et parlées",
    ["Typed lines"] = "Répliques tapées",
    ["Voice AI and microphone"] = "IA vocale et microphone",
    ["V’s voice engine"] = "Moteur vocal de V",
    ["Where V is: the district, and V’s apartment or the named place when the game says so.\n\nOff: characters are not told where you are, and the mod stops reading it from the game. The vision Convai has of what V sees, and an add-on’s own text, are not affected."] = "Où se trouve V: le quartier, l'appartement de V ou le lieu nommé quand le jeu le précise.\n\nDésactivé: les personnages ne sont pas informés de l'endroit où vous êtes, et le mod cesse de le lire dans le jeu. La vision que Convai reçoit de ce que voit V, et le texte propre d'un module complémentaire, ne sont pas affectés.",
    ["Who writes the replies."] = "Qui écrit les réponses.",
    ["Who you can talk to and what they know."] = "À qui vous pouvez parler et ce qu'ils savent.",
    ["Your AMD Radeon card can run OmniVoice. Set it up in Settings > Voice AI and microphone > OmniVoice for AMD: one download, then it starts by itself. Until then Pocket speaks."] = "Votre carte AMD Radeon peut exécuter OmniVoice. Configurez-la dans Paramètres > IA vocale et microphone > OmniVoice pour AMD: un téléchargement, puis il démarre tout seul. D'ici là, c'est Pocket qui parle.",
    ["Your Custom endpoint does not accept vision, so replies use only your words."] = "Votre endpoint Custom n'accepte pas la vision, les réponses n'utilisent donc que vos mots.",
    ["Search"] = "Rechercher",
    ["Type a name to search"] = "Tapez un nom à rechercher",
}
